async function init(){
  await pool.query(fs.readFileSync('./schema.sql','utf8'));
  const email=process.env.SAAS_ADMIN_EMAIL||'admin@owltechsolutionsltd.com';
  const password=process.env.SAAS_ADMIN_PASSWORD||'ChangeMeNow123!';
  let q=await pool.query('SELECT id FROM users WHERE lower(email)=lower($1)',[email]);
  let uid;
  if(!q.rowCount){const hash=await bcrypt.hash(password,12);const x=await pool.query('INSERT INTO users(email,password_hash,name,role) VALUES($1,$2,$3,$4) RETURNING id',[email,hash,'SaaS Administrator','saas_admin']);uid=x.rows[0].id}else uid=q.rows[0].id;

}
function auth(req,res,next){
  const h=req.headers.authorization||'',t=h.startsWith('Bearer ')?h.slice(7):null;
  if(!t)return res.status(401).json({error:'Unauthorized'});
  try{req.user=jwt.verify(t,secret);next()}catch{return res.status(401).json({error:'Invalid session'})}
}
async function tenant(req,res,next){
  if(req.user.role==='saas_admin'){req.businessId=Number(req.headers['x-business-id']||0)||null;return next()}
  const q=await pool.query('SELECT ub.business_id,b.status,b.trial_ends_at FROM user_businesses ub JOIN businesses b ON b.id=ub.business_id WHERE ub.user_id=$1 AND ub.active=true ORDER BY ub.business_id LIMIT 1',[req.user.id]);
  if(!q.rowCount)return res.status(403).json({error:'No active tenant'});
  req.businessId=q.rows[0].business_id; req.tenant=q.rows[0]; next();
}

async function createPasswordReset(userId){
  const raw=crypto.randomBytes(32).toString('hex');
  const hash=crypto.createHash('sha256').update(raw).digest('hex');
  await pool.query("UPDATE password_reset_tokens SET used_at=now() WHERE user_id=$1 AND used_at IS NULL",[userId]);
  await pool.query("INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES($1,$2,now()+interval '30 minutes')",[userId,hash]);
  return raw;
}
async function sendResetEmail(to,link){
  const key=process.env.RESEND_API_KEY||'';
  const from=process.env.RESET_FROM_EMAIL||'';
  if(!key||!from)return false;
  const r=await fetch('https://api.resend.com/emails',{method:'POST',headers:{'Authorization':'Bearer '+key,'Content-Type':'application/json'},body:JSON.stringify({from,to:[to],subject:'Reset your MauzoPOS password',html:'<div style="font-family:Arial,sans-serif;max-width:560px;margin:auto"><h2>MauzoPOS password reset</h2><p>Use the button below to create a new password. This link expires in 30 minutes.</p><p><a href="'+link+'" style="display:inline-block;background:#22A53A;color:#fff;text-decoration:none;padding:12px 18px;border-radius:10px;font-weight:700">Reset password</a></p><p style="color:#667085;font-size:12px">If you did not request this, ignore this email.</p></div>'})});
  return r.ok;
}

async function getBusinessRoles(req,bid){
  if(req.user.role==='saas_admin')return ['saas_admin'];
  const q=await pool.query('SELECT role FROM user_business_roles WHERE user_id=$1 AND business_id=$2 ORDER BY is_primary DESC,created_at,role',[req.user.id,bid]);
  if(q.rowCount)return q.rows.map(x=>x.role);
  const legacy=await pool.query('SELECT role FROM user_businesses WHERE user_id=$1 AND business_id=$2 AND active=true',[req.user.id,bid]);
  return legacy.rows.map(x=>x.role).filter(Boolean);
}
async function hasPermission(req,bid,code){
  if(req.user.role==='saas_admin')return true;
  const roles=await getBusinessRoles(req,bid);
  if(roles.some(role=>['owner','administrator','admin'].includes(role)))return true;
  if(!roles.length)return false;
  const q=await pool.query('SELECT 1 FROM role_permissions WHERE business_id=$1 AND role=ANY($2::text[]) AND permission_code=$3 AND allowed=true LIMIT 1',[bid,roles,code]);
  return q.rowCount>0;
}
function permit(code){return async(req,res,next)=>{try{const bid=await getBiz(req);if(!(await hasPermission(req,bid,code)))return res.status(403).json({error:'Permission denied'});next()}catch(e){res.status(500).json({error:e.message})}}}
function rolesAllowed(...allowed){return async(req,res,next)=>{try{if(req.user.role==='saas_admin')return next();const bid=await getBiz(req),roles=await getBusinessRoles(req,bid);if(!roles.some(r=>allowed.includes(r)))return res.status(403).json({error:'Permission denied'});next()}catch(e){res.status(500).json({error:e.message})}}}

async function getBusinessRole(req,bid){
  const roles=await getBusinessRoles(req,bid);
  return roles[0]||null;
}
async function approvalTarget(client,bid,actionType){
  const r=await client.query('SELECT * FROM approval_rules WHERE business_id=$1 AND action_type=$2 AND active=true',[bid,actionType]);
  if(!r.rowCount)return {approverUserId:null,approverRole:'owner'};
  return {approverUserId:r.rows[0].approver_user_id||null,approverRole:r.rows[0].approver_role||'owner'};
}
async function canDecideApproval(client,req,bid,approval){
  if(req.user.role==='saas_admin')return true;
  if(approval.approver_user_id&&Number(approval.approver_user_id)===Number(req.user.id))return true;
  const q=await client.query('SELECT role FROM user_business_roles WHERE user_id=$1 AND business_id=$2',[req.user.id,bid]);
  let roles=q.rows.map(x=>x.role);
  if(!roles.length){const legacy=await client.query('SELECT role FROM user_businesses WHERE user_id=$1 AND business_id=$2 AND active=true',[req.user.id,bid]);roles=legacy.rows.map(x=>x.role)}
  if(roles.some(role=>['owner','administrator','admin'].includes(role)))return true;
  return approval.approver_role?roles.includes(approval.approver_role):false;
}

async function getBiz(req){if(req.businessId)return req.businessId;const q=await pool.query('SELECT id FROM businesses ORDER BY id LIMIT 1');return q.rows[0]?.id}
async function audit(user,businessId,action,entity,id,details={}){try{await pool.query('INSERT INTO audit_logs(user_email,business_id,action,entity,entity_id,details) VALUES($1,$2,$3,$4,$5,$6)',[user?.email||null,businessId||null,action,entity,id?String(id):null,details])}catch{}}
