app.post('/api/customers/:id/account-payments',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),amount=Math.max(0,Number(req.body?.amount||0)),method=paymentMethodName(req.body?.method||'cash'),reference=String(req.body?.reference||'').trim()||null,tendered=Number(req.body?.tenderedAmount??amount),client=await pool.connect();if(!(amount>0))return res.status(400).json({error:'Payment amount must be positive'});try{await client.query('BEGIN');const cq=await client.query('SELECT * FROM customers WHERE id=$1 AND business_id=$2 FOR UPDATE',[id,bid]);if(!cq.rowCount)throw new Error('Customer not found');const customer=cq.rows[0],balance=Number(customer.balance||0);if(amount>balance+0.005)throw new Error('Payment exceeds customer account balance');if(method==='cash'&&tendered+0.005<amount)throw new Error('Cash tendered cannot be less than payment amount');const shift=await client.query("SELECT id,branch_id FROM cash_sessions WHERE business_id=$1 AND opened_by_user_id=$2 AND status='open' ORDER BY id DESC LIMIT 1",[bid,req.user.id]);if(method==='cash'&&!shift.rowCount)throw new Error('Open your cashier shift before receiving a cash account payment');const paymentNo=makeDocNo('PAY'),change=method==='cash'?Math.max(0,tendered-amount):0,p=await client.query("INSERT INTO payments(business_id,branch_id,customer_id,payment_no,payment_method,amount,tendered_amount,change_amount,reference,status,received_by,received_by_user_id,cash_session_id) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9,'posted',$10,$11,$12) RETURNING *",[bid,shift.rows[0]?.branch_id||null,id,paymentNo,method,amount,method==='cash'?tendered:amount,change,reference,req.user.name,req.user.id,shift.rows[0]?.id||null]);let remaining=amount;const sales=await client.query("SELECT * FROM sales WHERE business_id=$1 AND customer_id=$2 AND voided=false AND balance_due>0 ORDER BY created_at,id FOR UPDATE",[bid,id]);for(const sale of sales.rows){if(remaining<=0.005)break;const alloc=Math.min(remaining,Number(sale.balance_due||0));if(!(alloc>0))continue;await client.query("INSERT INTO payment_allocations(business_id,payment_id,source_type,source_id,amount) VALUES($1,$2,'sale',$3,$4)",[bid,p.rows[0].id,sale.id,alloc]);const paid=Number(sale.amount_paid||0)+alloc,due=Math.max(0,Number(sale.total)-paid),status=due<=0.005?'paid':'partially_paid';await client.query("UPDATE sales SET amount_paid=$1,balance_due=$2,payment_status=$3,payment_method=CASE WHEN payment_method IN ('pending','credit') THEN $4 WHEN payment_method=$4 THEN payment_method ELSE 'split' END WHERE id=$5",[paid,due,status,method,sale.id]);remaining-=alloc}if(remaining>0.005)throw new Error('Could not allocate the full customer payment to outstanding sales');await customerLedgerEntry(client,{bid,customerId:id,entryType:'account_payment',sourceType:'customer_account',sourceId:id,referenceNo:paymentNo,credit:amount,notes:'Customer account payment'+(reference?' · '+reference:''),userName:req.user.name,userId:req.user.id});await client.query('COMMIT');await audit(req.user,bid,'account_payment','customer',id,{paymentNo,amount,method});res.json({ok:true,payment:p.rows[0],balance:Math.max(0,balance-amount)})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

