app.get('/api/kitchen/tickets',auth,tenant,async(req,res)=>{const bid=await getBiz(req),stationId=Number(req.query.stationId||0),status=req.query.status||'active';const p=[bid];let where="kt.business_id=$1";if(stationId){p.push(stationId);where+=" AND kt.station_id=$2"}if(status==='active')where+=" AND kt.status IN ('new','preparing','ready')";else if(status!=='all'){p.push(status);where+=" AND kt.status=$"+p.length}const q=await pool.query("SELECT kt.*,ks.name station_name,ks.station_type,o.order_no,o.order_type,o.waiter_name,t.name table_name,extract(epoch from (now()-kt.created_at))/60 elapsed_minutes,coalesce(json_agg(json_build_object('id',ki.id,'orderItemId',ki.order_item_id,'name',ki.product_name,'qty',ki.qty,'notes',ki.notes,'status',ki.status,'startedAt',ki.started_at,'readyAt',ki.ready_at,'servedAt',ki.served_at) ORDER BY ki.id) FILTER (WHERE ki.id IS NOT NULL),'[]'::json) items FROM kitchen_tickets kt LEFT JOIN kitchen_stations ks ON ks.id=kt.station_id JOIN restaurant_orders o ON o.id=kt.order_id LEFT JOIN restaurant_tables t ON t.id=o.table_id LEFT JOIN kitchen_ticket_items ki ON ki.ticket_id=kt.id WHERE "+where+" GROUP BY kt.id,ks.name,ks.station_type,o.order_no,o.order_type,o.waiter_name,t.name ORDER BY CASE kt.priority WHEN 'rush' THEN 0 ELSE 1 END,kt.created_at",[...p]);res.json(q.rows)});
