app.put('/api/kitchen/tickets/:id/status',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),to=String(req.body?.status||''),client=await pool.connect();const allowed={new:['preparing'],preparing:['ready'],ready:['served']};try{await client.query('BEGIN');const t=await client.query('SELECT * FROM kitchen_tickets WHERE id=$1 AND business_id=$2 FOR UPDATE',[id,bid]);if(!t.rowCount)throw new Error('Kitchen ticket not found');if(!(allowed[t.rows[0].status]||[]).includes(to))throw new Error('Invalid kitchen ticket transition');const nowCol=to==='preparing'?'started_at':to==='ready'?'ready_at':'completed_at';await client.query("UPDATE kitchen_tickets SET status=$1,"+nowCol+"=coalesce("+nowCol+",now()) WHERE id=$2",[to,id]);const itemCol=to==='preparing'?'started_at':to==='ready'?'ready_at':'served_at';await client.query("UPDATE kitchen_ticket_items SET status=$1,"+itemCol+"=coalesce("+itemCol+",now()) WHERE ticket_id=$2 AND status<>'served'",[to,id]);const mapped=to==='preparing'?'preparing':to==='ready'?'ready':'served';await client.query("UPDATE restaurant_order_items oi SET status=$1 FROM kitchen_ticket_items ki WHERE ki.ticket_id=$2 AND ki.order_item_id=oi.id",[mapped,id]);await client.query("INSERT INTO kitchen_events(business_id,ticket_id,event_type,from_status,to_status,changed_by) VALUES($1,$2,'ticket_status',$3,$4,$5)",[bid,id,t.rows[0].status,to,req.user.name]);const orderStatus=await syncRestaurantOrderFromKitchen(client,Number(t.rows[0].order_id));if(orderStatus&&orderStatus!==t.rows[0].status)await client.query("INSERT INTO restaurant_order_status_history(order_id,from_status,to_status,comment,changed_by) SELECT id,status,$1,'Kitchen status sync',$2 FROM restaurant_orders WHERE id=$3",[orderStatus,req.user.name,t.rows[0].order_id]);await client.query('COMMIT');res.json({ok:true,status:to,orderStatus})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.put('/api/kitchen/items/:id/status',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),to=String(req.body?.status||''),client=await pool.connect();const allowed={new:['preparing'],preparing:['ready'],ready:['served']};try{await client.query('BEGIN');const i=await client.query("SELECT ki.*,kt.business_id,kt.order_id,kt.id ticket_id FROM kitchen_ticket_items ki JOIN kitchen_tickets kt ON kt.id=ki.ticket_id WHERE ki.id=$1 AND kt.business_id=$2 FOR UPDATE OF ki,kt",[id,bid]);if(!i.rowCount)throw new Error('Kitchen item not found');if(!(allowed[i.rows[0].status]||[]).includes(to))throw new Error('Invalid kitchen item transition');const col=to==='preparing'?'started_at':to==='ready'?'ready_at':'served_at';await client.query("UPDATE kitchen_ticket_items SET status=$1,"+col+"=coalesce("+col+",now()) WHERE id=$2",[to,id]);await client.query("UPDATE restaurant_order_items SET status=$1 WHERE id=$2",[to==='preparing'?'preparing':to==='ready'?'ready':'served',i.rows[0].order_item_id]);const ticket=await client.query("SELECT count(*) FILTER (WHERE status='new')::int n,count(*) FILTER (WHERE status='preparing')::int p,count(*) FILTER (WHERE status='ready')::int r,count(*) FILTER (WHERE status='served')::int s,count(*)::int total FROM kitchen_ticket_items WHERE ticket_id=$1",[i.rows[0].ticket_id]);const x=ticket.rows[0];let ticketStatus=x.s===x.total?'served':(x.r+x.s===x.total?'ready':(x.p+x.r+x.s>0?'preparing':'new'));await client.query("UPDATE kitchen_tickets SET status=$1,started_at=CASE WHEN $1='preparing' THEN coalesce(started_at,now()) ELSE started_at END,ready_at=CASE WHEN $1='ready' THEN coalesce(ready_at,now()) ELSE ready_at END,completed_at=CASE WHEN $1='served' THEN coalesce(completed_at,now()) ELSE completed_at END WHERE id=$2",[ticketStatus,i.rows[0].ticket_id]);await client.query("INSERT INTO kitchen_events(business_id,ticket_id,order_item_id,event_type,from_status,to_status,changed_by) VALUES($1,$2,$3,'item_status',$4,$5,$6)",[bid,i.rows[0].ticket_id,i.rows[0].order_item_id,i.rows[0].status,to,req.user.name]);await syncRestaurantOrderFromKitchen(client,Number(i.rows[0].order_id));await client.query('COMMIT');res.json({ok:true,status:to,ticketStatus})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.put('/api/kitchen/tickets/:id/priority',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),priority=req.body?.priority==='rush'?'rush':'normal';const q=await pool.query('UPDATE kitchen_tickets SET priority=$1 WHERE id=$2 AND business_id=$3 RETURNING *',[priority,id,bid]);if(!q.rowCount)return res.status(404).json({error:'Kitchen ticket not found'});await pool.query("INSERT INTO kitchen_events(business_id,ticket_id,event_type,to_status,changed_by) VALUES($1,$2,'priority',$3,$4)",[bid,id,priority,req.user.name]);res.json(q.rows[0])});
app.post('/api/kitchen/tickets/:id/reprint',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id);const q=await pool.query('UPDATE kitchen_tickets SET printed_count=printed_count+1 WHERE id=$1 AND business_id=$2 RETURNING *',[id,bid]);if(!q.rowCount)return res.status(404).json({error:'Kitchen ticket not found'});await pool.query("INSERT INTO kitchen_events(business_id,ticket_id,event_type,notes,changed_by) VALUES($1,$2,'reprint','Kitchen ticket reprint requested',$3)",[bid,id,req.user.name]);res.json({ok:true,printedCount:q.rows[0].printed_count})});

app.get('/api/restaurant/reservations',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const q=await pool.query("SELECT r.*,t.name table_name,b.name branch_name,c.name customer_name FROM restaurant_reservations r LEFT JOIN restaurant_tables t ON t.id=r.table_id JOIN branches b ON b.id=r.branch_id LEFT JOIN customers c ON c.id=r.customer_id WHERE r.business_id=$1 AND r.reserved_at>=now()-interval '1 day' ORDER BY r.reserved_at",[bid]);res.json(q.rows)});
app.post('/api/restaurant/reservations',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const {branchId,tableId=null,customerId=null,guestName=null,phone=null,guestCount=1,reservedAt,durationMinutes=120,notes=null}=req.body||{};if(!branchId||!reservedAt)return res.status(400).json({error:'Branch and reservation time are required'});const q=await pool.query("INSERT INTO restaurant_reservations(business_id,branch_id,table_id,customer_id,guest_name,phone,guest_count,reserved_at,duration_minutes,status,notes,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9,'reserved',$10,$11) RETURNING *",[bid,branchId,tableId||null,customerId||null,guestName||null,phone||null,Math.max(1,Number(guestCount||1)),reservedAt,Math.max(15,Number(durationMinutes||120)),notes||null,req.user.name]);if(tableId)await pool.query("UPDATE restaurant_tables SET status=CASE WHEN status='available' THEN 'reserved' ELSE status END WHERE id=$1 AND business_id=$2",[tableId,bid]);res.json(q.rows[0])});
app.put('/api/restaurant/reservations/:id/status',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),status=String(req.body?.status||'');if(!['reserved','seated','completed','cancelled','no_show'].includes(status))return res.status(400).json({error:'Invalid reservation status'});const q=await pool.query('UPDATE restaurant_reservations SET status=$1 WHERE id=$2 AND business_id=$3 RETURNING *',[status,id,bid]);if(!q.rowCount)return res.status(404).json({error:'Reservation not found'});if(['cancelled','completed','no_show'].includes(status)&&q.rows[0].table_id)await pool.query("UPDATE restaurant_tables SET status='available',cleanliness_status='dirty' WHERE id=$1 AND business_id=$2 AND status='reserved'",[q.rows[0].table_id,bid]);res.json(q.rows[0])});

