app.post('/api/restaurant/tables',auth,tenant,rolesAllowed('owner','administrator','admin','branch_manager','restaurant_manager'),async(req,res)=>{const bid=await getBiz(req);const {branchId,areaId=null,name,code=null,capacity=2,status='available',cleanlinessStatus='clean',sortOrder=0}=req.body||{};if(!branchId||!name?.trim())return res.status(400).json({error:'Branch and table name are required'});const safeStatus=['available','reserved','occupied'].includes(status)?status:'available',safeClean=['clean','dirty'].includes(cleanlinessStatus)?cleanlinessStatus:'clean';const q=await pool.query('INSERT INTO restaurant_tables(business_id,branch_id,area_id,name,code,capacity,status,cleanliness_status,sort_order) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *',[bid,branchId,areaId||null,name.trim(),code||null,Math.max(1,Number(capacity||2)),safeStatus,safeClean,Number(sortOrder||0)]);res.json(q.rows[0])});
app.put('/api/restaurant/tables/:id',auth,tenant,rolesAllowed('owner','administrator','admin','branch_manager','restaurant_manager'),async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id);const {areaId=null,name,code=null,capacity=2,status='available',cleanlinessStatus='clean',sortOrder=0,active=true}=req.body||{};const safeStatus=['available','reserved','occupied'].includes(status)?status:'available',safeClean=['clean','dirty'].includes(cleanlinessStatus)?cleanlinessStatus:'clean';const q=await pool.query('UPDATE restaurant_tables SET area_id=$1,name=$2,code=$3,capacity=$4,status=$5,cleanliness_status=$6,sort_order=$7,active=$8 WHERE id=$9 AND business_id=$10 RETURNING *',[areaId||null,name,code||null,Math.max(1,Number(capacity||2)),safeStatus,safeClean,Number(sortOrder||0),!!active,id,bid]);if(!q.rowCount)return res.status(404).json({error:'Table not found'});res.json(q.rows[0])});

app.put('/api/restaurant/tables/:id/state',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),{status,cleanlinessStatus}=req.body||{};const sets=[],vals=[];if(status!==undefined){if(!['available','reserved','occupied'].includes(status))return res.status(400).json({error:'Invalid table occupancy status'});vals.push(status);sets.push('status=$'+vals.length)}if(cleanlinessStatus!==undefined){if(!['clean','dirty'].includes(cleanlinessStatus))return res.status(400).json({error:'Invalid cleanliness status'});vals.push(cleanlinessStatus);sets.push('cleanliness_status=$'+vals.length)}if(!sets.length)return res.status(400).json({error:'Nothing to update'});vals.push(id,bid);const q=await pool.query('UPDATE restaurant_tables SET '+sets.join(',')+' WHERE id=$'+(vals.length-1)+' AND business_id=$'+vals.length+' RETURNING *',vals);if(!q.rowCount)return res.status(404).json({error:'Table not found'});res.json(q.rows[0])});

