app.post('/api/menu/categories',auth,tenant,rolesAllowed('owner','administrator','admin','branch_manager','restaurant_manager'),async(req,res)=>{const bid=await getBiz(req);const {name,parentId=null,description=null,defaultStationId=null,sortOrder=0}=req.body||{};if(!name?.trim())return res.status(400).json({error:'Category name is required'});const q=await pool.query('INSERT INTO menu_categories(business_id,parent_id,name,description,default_station_id,sort_order) VALUES($1,$2,$3,$4,$5,$6) RETURNING *',[bid,parentId||null,name.trim(),description||null,defaultStationId||null,Number(sortOrder||0)]);res.json(q.rows[0])});
