app.get('/api/menu/modifier-groups',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const q=await pool.query("SELECT g.*,coalesce(json_agg(json_build_object('id',m.id,'name',m.name,'price',m.price,'active',m.active,'sortOrder',m.sort_order) ORDER BY m.sort_order,m.name) FILTER (WHERE m.id IS NOT NULL),'[]'::json) modifiers FROM modifier_groups g LEFT JOIN modifiers m ON m.modifier_group_id=g.id AND m.active=true WHERE g.business_id=$1 AND g.active=true GROUP BY g.id ORDER BY g.sort_order,g.name",[bid]);res.json(q.rows)});
app.post('/api/menu/modifier-groups',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const {id=null,name,required=false,minSelect=0,maxSelect=1,modifiers:mods=[]}=req.body||{};if(!name?.trim())return res.status(400).json({error:'Modifier group name is required'});const client=await pool.connect();try{await client.query('BEGIN');let g;if(id){g=await client.query('UPDATE modifier_groups SET name=$1,required=$2,min_select=$3,max_select=$4 WHERE id=$5 AND business_id=$6 RETURNING *',[name.trim(),!!required,Number(minSelect||0),Math.max(Number(maxSelect||1),Number(minSelect||0)),id,bid]);if(!g.rowCount)throw new Error('Modifier group not found')}else g=await client.query('INSERT INTO modifier_groups(business_id,name,required,min_select,max_select) VALUES($1,$2,$3,$4,$5) RETURNING *',[bid,name.trim(),!!required,Number(minSelect||0),Math.max(Number(maxSelect||1),Number(minSelect||0))]);await client.query('DELETE FROM modifiers WHERE modifier_group_id=$1',[g.rows[0].id]);for(const m of mods){if(!m.name?.trim())continue;await client.query('INSERT INTO modifiers(modifier_group_id,name,price,sort_order) VALUES($1,$2,$3,$4)',[g.rows[0].id,m.name.trim(),Number(m.price||0),Number(m.sortOrder||0)])}await client.query('COMMIT');res.json(g.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

app.get('/api/menu/items',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const q=await pool.query("SELECT mi.*,p.name product_name,p.price base_price,p.sku,p.barcode,c.name category_name,s.name station_name,(SELECT count(*) FROM menu_variants v WHERE v.menu_item_id=mi.id AND v.active=true)::int variant_count,(SELECT count(*) FROM menu_item_modifier_groups mg WHERE mg.menu_item_id=mi.id)::int modifier_group_count FROM menu_items mi JOIN products p ON p.id=mi.product_id LEFT JOIN menu_categories c ON c.id=mi.category_id LEFT JOIN kitchen_stations s ON s.id=coalesce(mi.kitchen_station_id,c.default_station_id) WHERE mi.business_id=$1 ORDER BY mi.sort_order,p.name",[bid]);res.json(q.rows)});
app.get('/api/menu/items/:id',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id);const h=await pool.query("SELECT mi.*,p.name product_name,p.price base_price FROM menu_items mi JOIN products p ON p.id=mi.product_id WHERE mi.id=$1 AND mi.business_id=$2",[id,bid]);if(!h.rowCount)return res.status(404).json({error:'Menu item not found'});const [variants,groups,prices,schedules]=await Promise.all([pool.query('SELECT * FROM menu_variants WHERE menu_item_id=$1 AND active=true ORDER BY sort_order,name',[id]),pool.query('SELECT modifier_group_id FROM menu_item_modifier_groups WHERE menu_item_id=$1 ORDER BY sort_order',[id]),pool.query('SELECT * FROM menu_item_prices WHERE menu_item_id=$1 ORDER BY branch_id,order_type',[id]),pool.query('SELECT * FROM menu_item_schedules WHERE menu_item_id=$1 AND active=true ORDER BY day_of_week,start_time',[id])]);res.json({item:h.rows[0],variants:variants.rows,modifierGroupIds:groups.rows.map(x=>Number(x.modifier_group_id)),prices:prices.rows,schedules:schedules.rows})});
app.post('/api/menu/items',auth,tenant,rolesAllowed('owner','administrator','admin','branch_manager','restaurant_manager'),async(req,res)=>{const bid=await getBiz(req);const {id=null,productId,categoryId=null,kitchenStationId=null,description=null,imageUrl=null,available=true,soldOut=false,sortOrder=0,variants=[],modifierGroupIds=[],prices=[],schedules=[]}=req.body||{};if(!productId)return res.status(400).json({error:'Product is required'});const client=await pool.connect();try{await client.query('BEGIN');const p=await client.query('SELECT id,name FROM products WHERE id=$1 AND business_id=$2 AND active=true AND sellable=true',[productId,bid]);if(!p.rowCount)throw new Error('Sellable product not found');let mi;if(id){mi=await client.query('UPDATE menu_items SET product_id=$1,category_id=$2,kitchen_station_id=$3,description=$4,image_url=$5,available=$6,sold_out=$7,sort_order=$8,updated_at=now() WHERE id=$9 AND business_id=$10 RETURNING *',[productId,categoryId||null,kitchenStationId||null,description||null,imageUrl||null,!!available,!!soldOut,Number(sortOrder||0),id,bid]);if(!mi.rowCount)throw new Error('Menu item not found')}else{mi=await client.query("INSERT INTO menu_items(business_id,product_id,category_id,kitchen_station_id,description,image_url,available,sold_out,sort_order) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT(business_id,product_id) DO UPDATE SET category_id=EXCLUDED.category_id,kitchen_station_id=EXCLUDED.kitchen_station_id,description=EXCLUDED.description,image_url=EXCLUDED.image_url,available=EXCLUDED.available,sold_out=EXCLUDED.sold_out,sort_order=EXCLUDED.sort_order,updated_at=now() RETURNING *",[bid,productId,categoryId||null,kitchenStationId||null,description||null,imageUrl||null,!!available,!!soldOut,Number(sortOrder||0)])}const mid=mi.rows[0].id;await client.query('DELETE FROM menu_variants WHERE menu_item_id=$1',[mid]);for(const v of variants){if(!v.name?.trim())continue;await client.query('INSERT INTO menu_variants(menu_item_id,name,sku,price_delta,sort_order) VALUES($1,$2,$3,$4,$5)',[mid,v.name.trim(),v.sku||null,Number(v.priceDelta||0),Number(v.sortOrder||0)])}await client.query('DELETE FROM menu_item_modifier_groups WHERE menu_item_id=$1',[mid]);for(const [idx,gid] of [...new Set(modifierGroupIds.map(Number).filter(Boolean))].entries())await client.query('INSERT INTO menu_item_modifier_groups(menu_item_id,modifier_group_id,sort_order) VALUES($1,$2,$3)',[mid,gid,idx]);await client.query('DELETE FROM menu_item_prices WHERE menu_item_id=$1',[mid]);for(const pr of prices){if(!pr.branchId||!(Number(pr.price)>=0))continue;await client.query('INSERT INTO menu_item_prices(menu_item_id,branch_id,order_type,price) VALUES($1,$2,$3,$4)',[mid,pr.branchId,pr.orderType||'all',Number(pr.price)])}await client.query('DELETE FROM menu_item_schedules WHERE menu_item_id=$1',[mid]);for(const sc of schedules){if(sc.dayOfWeek===undefined||!sc.startTime||!sc.endTime)continue;await client.query('INSERT INTO menu_item_schedules(menu_item_id,day_of_week,start_time,end_time) VALUES($1,$2,$3,$4)',[mid,Number(sc.dayOfWeek),sc.startTime,sc.endTime])}await client.query('COMMIT');res.json(mi.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.put('/api/menu/items/:id/config',auth,tenant,rolesAllowed('owner','administrator','admin','branch_manager','restaurant_manager'),permit('settings.manage'),async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),{categoryId=null,kitchenStationId=null,price,available=true,soldOut=false,description=null}=req.body||{};const client=await pool.connect();try{await client.query('BEGIN');const mi=await client.query('UPDATE menu_items SET category_id=$1,kitchen_station_id=$2,description=coalesce($3,description),available=$4,sold_out=$5,updated_at=now() WHERE id=$6 AND business_id=$7 RETURNING *',[categoryId||null,kitchenStationId||null,description,!!available,!!soldOut,id,bid]);if(!mi.rowCount)throw new Error('Menu item not found');if(price!==undefined&&Number(price)>=0)await client.query('UPDATE products SET price=$1 WHERE id=$2 AND business_id=$3',[Number(price),mi.rows[0].product_id,bid]);await client.query('COMMIT');res.json(mi.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

app.put('/api/menu/items/:id/availability',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id);const {available,soldOut}=req.body||{};const q=await pool.query('UPDATE menu_items SET available=$1,sold_out=$2,updated_at=now() WHERE id=$3 AND business_id=$4 RETURNING *',[!!available,!!soldOut,id,bid]);if(!q.rowCount)return res.status(404).json({error:'Menu item not found'});res.json(q.rows[0])});

app.get('/api/menu/combos',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const q=await pool.query("SELECT c.*,p.name product_name,p.price,coalesce(json_agg(json_build_object('menuItemId',mi.id,'name',ip.name,'qty',ci.qty,'required',ci.required)) FILTER (WHERE ci.id IS NOT NULL),'[]'::json) items FROM menu_combos c JOIN products p ON p.id=c.product_id LEFT JOIN menu_combo_items ci ON ci.combo_id=c.id LEFT JOIN menu_items mi ON mi.id=ci.menu_item_id LEFT JOIN products ip ON ip.id=mi.product_id WHERE c.business_id=$1 AND c.active=true GROUP BY c.id,p.name,p.price ORDER BY c.name",[bid]);res.json(q.rows)});
app.post('/api/menu/combos',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const {id=null,productId,name,description=null,items=[]}=req.body||{};if(!productId||!name?.trim()||!Array.isArray(items)||!items.length)return res.status(400).json({error:'Combo product, name and component items are required'});const client=await pool.connect();try{await client.query('BEGIN');let c;if(id){c=await client.query('UPDATE menu_combos SET product_id=$1,name=$2,description=$3,active=true WHERE id=$4 AND business_id=$5 RETURNING *',[productId,name.trim(),description||null,id,bid]);if(!c.rowCount)throw new Error('Combo not found')}else c=await client.query("INSERT INTO menu_combos(business_id,product_id,name,description) VALUES($1,$2,$3,$4) ON CONFLICT(business_id,product_id) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,active=true RETURNING *",[bid,productId,name.trim(),description||null]);await client.query('DELETE FROM menu_combo_items WHERE combo_id=$1',[c.rows[0].id]);for(const x of items){if(!x.menuItemId||!(Number(x.qty)>0))continue;await client.query('INSERT INTO menu_combo_items(combo_id,menu_item_id,qty,required) VALUES($1,$2,$3,$4)',[c.rows[0].id,x.menuItemId,Number(x.qty),x.required!==false])}await client.query('COMMIT');res.json(c.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

app.get('/api/menu/available',auth,tenant,async(req,res)=>{const bid=await getBiz(req),orderType=String(req.query.orderType||'counter'),branchId=Number(req.query.branchId||0);let branch=branchId;if(!branch){const b=await pool.query('SELECT id FROM branches WHERE business_id=$1 AND active=true ORDER BY id LIMIT 1',[bid]);branch=Number(b.rows[0]?.id||0)}const q=await pool.query("SELECT p.id,p.name,p.sku,p.product_code,p.barcode,p.stock,p.price base_price,mi.id menu_item_id,mi.description,mi.image_url,mi.category_id,c.name category_name,mi.sold_out,mi.available,coalesce((SELECT mp.price FROM menu_item_prices mp WHERE mp.menu_item_id=mi.id AND mp.branch_id=$2 AND mp.order_type IN ($3,'all') ORDER BY CASE WHEN mp.order_type=$3 THEN 0 ELSE 1 END LIMIT 1),p.price)::numeric resolved_price FROM products p LEFT JOIN menu_items mi ON mi.product_id=p.id AND mi.business_id=p.business_id LEFT JOIN menu_categories c ON c.id=mi.category_id WHERE p.business_id=$1 AND p.active=true AND p.sellable=true AND (mi.id IS NULL OR (mi.available=true AND mi.sold_out=false)) AND (mi.id IS NULL OR NOT EXISTS(SELECT 1 FROM menu_item_schedules ms WHERE ms.menu_item_id=mi.id AND ms.active=true) OR EXISTS(SELECT 1 FROM menu_item_schedules ms WHERE ms.menu_item_id=mi.id AND ms.active=true AND ms.day_of_week=extract(dow from now())::int AND current_time BETWEEN ms.start_time AND ms.end_time)) ORDER BY coalesce(c.sort_order,999),coalesce(mi.sort_order,999),p.name",[bid,branch,orderType]);res.json(q.rows)});

app.get('/api/units',auth,tenant,async(req,res)=>{const bid=await getBiz(req);res.json((await pool.query('SELECT * FROM units_of_measure WHERE business_id=$1 AND active=true ORDER BY unit_type,name',[bid])).rows)});
app.post('/api/units',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const {name,symbol,unitType='count',baseFactor=1}=req.body||{};if(!name?.trim()||!symbol?.trim()||!(Number(baseFactor)>0))return res.status(400).json({error:'Name, symbol and positive conversion factor are required'});try{const q=await pool.query('INSERT INTO units_of_measure(business_id,name,symbol,unit_type,base_factor) VALUES($1,$2,$3,$4,$5) RETURNING *',[bid,name.trim(),symbol.trim(),unitType,Number(baseFactor)]);res.json(q.rows[0])}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/inventory/items',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const q=await pool.query("SELECT p.*,u.name unit_name,u.symbol unit_symbol FROM products p LEFT JOIN units_of_measure u ON u.id=p.base_unit_id WHERE p.business_id=$1 AND p.active=true ORDER BY CASE p.item_type WHEN 'ingredient' THEN 0 ELSE 1 END,p.name",[bid]);res.json(q.rows)});
app.get('/api/ingredients',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const q=await pool.query("SELECT p.*,u.name unit_name,u.symbol unit_symbol,coalesce((SELECT sum(ib.qty) FROM inventory_balances ib WHERE ib.business_id=p.business_id AND ib.product_id=p.id),0)::numeric location_stock FROM products p LEFT JOIN units_of_measure u ON u.id=p.base_unit_id WHERE p.business_id=$1 AND p.item_type='ingredient' AND p.active=true ORDER BY p.name",[bid]);res.json(q.rows)});
app.post('/api/ingredients',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const {name,sku=null,baseUnitId,cost=0,reorderLevel=0,openingStock=0,locationId=null}=req.body||{};if(!name?.trim()||!baseUnitId)return res.status(400).json({error:'Ingredient name and base unit are required'});const client=await pool.connect();try{await client.query('BEGIN');const u=await client.query('SELECT id FROM units_of_measure WHERE id=$1 AND business_id=$2 AND active=true',[baseUnitId,bid]);if(!u.rowCount)throw new Error('Unit not found');const p=await client.query("INSERT INTO products(business_id,name,sku,category,cost,price,stock,reorder_level,item_type,sellable,base_unit_id) VALUES($1,$2,$3,'Ingredient',$4,0,0,$5,'ingredient',false,$6) RETURNING *",[bid,name.trim(),sku||null,Number(cost||0),Number(reorderLevel||0),baseUnitId]);if(Number(openingStock)>0){const lid=locationId?Number(locationId):await operationalStockLocation(client,bid,null);await inventoryBalanceChange(client,{bid,locationId:lid,productId:Number(p.rows[0].id),delta:Number(openingStock),unitCost:Number(cost||0),movementType:'opening_stock',referenceType:'INGREDIENT',referenceId:Number(p.rows[0].id),referenceNo:'OPEN-'+p.rows[0].id,notes:'Ingredient opening stock',userName:req.user.name,toLocationId:lid,updateProductCost:true})}await client.query('COMMIT');await audit(req.user,bid,'create','ingredient',p.rows[0].id,{name:name.trim()});res.json(p.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

app.put('/api/ingredients/:id',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id);const {name,sku=null,baseUnitId,cost=0,reorderLevel=0}=req.body||{};if(!name?.trim()||!baseUnitId)return res.status(400).json({error:'Ingredient name and base unit are required'});const client=await pool.connect();try{await client.query('BEGIN');const p=await client.query("SELECT p.*,coalesce((SELECT sum(qty) FROM inventory_balances ib WHERE ib.business_id=p.business_id AND ib.product_id=p.id),0)::numeric total_stock FROM products p WHERE p.id=$1 AND p.business_id=$2 AND p.item_type='ingredient' FOR UPDATE",[id,bid]);if(!p.rowCount)throw new Error('Ingredient not found');if(Number(p.rows[0].total_stock)!==0&&Number(p.rows[0].base_unit_id||0)!==Number(baseUnitId))throw new Error('Base unit cannot be changed while this ingredient has stock. Transfer/adjust stock to zero first.');const u=await client.query('SELECT id FROM units_of_measure WHERE id=$1 AND business_id=$2 AND active=true',[baseUnitId,bid]);if(!u.rowCount)throw new Error('Unit not found');const q=await client.query("UPDATE products SET name=$1,sku=$2,cost=$3,reorder_level=$4,base_unit_id=$5 WHERE id=$6 AND business_id=$7 RETURNING *",[name.trim(),sku||null,Number(cost||0),Number(reorderLevel||0),baseUnitId,id,bid]);await client.query('COMMIT');await audit(req.user,bid,'update','ingredient',id,{name:name.trim()});res.json(q.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/recipes',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const q=await pool.query("SELECT r.*,p.name product_name,p.price,l.name consumption_location,(SELECT count(*) FROM recipe_lines rl WHERE rl.recipe_id=r.id)::int line_count,coalesce((SELECT sum((rl.quantity*u.base_factor/coalesce(nullif(bu.base_factor,0),1))*(1+rl.waste_percent/100)*ip.cost) FROM recipe_lines rl JOIN units_of_measure u ON u.id=rl.unit_id JOIN products ip ON ip.id=rl.ingredient_product_id LEFT JOIN units_of_measure bu ON bu.id=ip.base_unit_id WHERE rl.recipe_id=r.id),0)::numeric recipe_cost FROM recipes r JOIN products p ON p.id=r.product_id LEFT JOIN inventory_locations l ON l.id=r.consumption_location_id WHERE r.business_id=$1 AND r.active=true ORDER BY p.name",[bid]);res.json(q.rows)});
app.get('/api/recipes/:id',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id);const h=await pool.query("SELECT r.*,p.name product_name FROM recipes r JOIN products p ON p.id=r.product_id WHERE r.id=$1 AND r.business_id=$2",[id,bid]);if(!h.rowCount)return res.status(404).json({error:'Recipe not found'});const lines=await pool.query("SELECT rl.*,p.name ingredient_name,u.symbol unit_symbol FROM recipe_lines rl JOIN products p ON p.id=rl.ingredient_product_id JOIN units_of_measure u ON u.id=rl.unit_id WHERE rl.recipe_id=$1 ORDER BY rl.id",[id]);res.json({recipe:h.rows[0],lines:lines.rows})});
app.post('/api/recipes',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const {productId,name,yieldQty=1,consumptionLocationId=null,lines=[]}=req.body||{};if(!productId||!name?.trim()||!(Number(yieldQty)>0)||!Array.isArray(lines)||!lines.length)return res.status(400).json({error:'Menu product, recipe name, positive yield and ingredients are required'});const clean=lines.map(x=>({ingredientProductId:Number(x.ingredientProductId),quantity:Number(x.quantity),unitId:Number(x.unitId),wastePercent:Number(x.wastePercent||0)})).filter(x=>x.ingredientProductId&&x.quantity>0&&x.unitId);if(clean.length!==lines.length)return res.status(400).json({error:'Every recipe line needs ingredient, quantity and unit'});const client=await pool.connect();try{await client.query('BEGIN');const product=await client.query("SELECT id,name FROM products WHERE id=$1 AND business_id=$2 AND active=true AND sellable=true",[productId,bid]);if(!product.rowCount)throw new Error('Menu product not found');if(consumptionLocationId){const l=await client.query('SELECT id FROM inventory_locations WHERE id=$1 AND business_id=$2 AND active=true',[consumptionLocationId,bid]);if(!l.rowCount)throw new Error('Consumption location not found')}const ingredientIds=clean.map(x=>x.ingredientProductId),ing=await client.query("SELECT id,base_unit_id FROM products WHERE business_id=$1 AND active=true AND item_type='ingredient' AND id=ANY($2::bigint[])",[bid,ingredientIds]);if(ing.rowCount!==new Set(ingredientIds).size)throw new Error('Recipe contains an invalid ingredient');const unitIds=clean.map(x=>x.unitId),units=await client.query('SELECT id,unit_type FROM units_of_measure WHERE business_id=$1 AND active=true AND id=ANY($2::bigint[])',[bid,unitIds]);if(units.rowCount!==new Set(unitIds).size)throw new Error('Recipe contains an invalid unit');const r=await client.query("INSERT INTO recipes(business_id,product_id,name,yield_qty,consumption_location_id,active) VALUES($1,$2,$3,$4,$5,true) ON CONFLICT(business_id,product_id) DO UPDATE SET name=EXCLUDED.name,yield_qty=EXCLUDED.yield_qty,consumption_location_id=EXCLUDED.consumption_location_id,active=true,updated_at=now() RETURNING *",[bid,productId,name.trim(),Number(yieldQty),consumptionLocationId||null]);await client.query('DELETE FROM recipe_lines WHERE recipe_id=$1',[r.rows[0].id]);for(const x of clean)await client.query('INSERT INTO recipe_lines(recipe_id,ingredient_product_id,quantity,unit_id,waste_percent) VALUES($1,$2,$3,$4,$5)',[r.rows[0].id,x.ingredientProductId,x.quantity,x.unitId,x.wastePercent]);await client.query('COMMIT');await audit(req.user,bid,'save','recipe',r.rows[0].id,{productId});res.json(r.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

app.delete('/api/recipes/:id',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id);const q=await pool.query("UPDATE recipes SET active=false,updated_at=now() WHERE id=$1 AND business_id=$2 RETURNING id",[id,bid]);if(!q.rowCount)return res.status(404).json({error:'Recipe not found'});await audit(req.user,bid,'archive','recipe',id,{});res.json({ok:true})});
app.post('/api/inventory/consumptions',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const {consumptionType,productId,qty=1,locationId=null,notes=null}=req.body||{};if(!['staff_meal','complimentary'].includes(consumptionType)||!productId||!(Number(qty)>0))return res.status(400).json({error:'Consumption type, product and positive quantity are required'});const client=await pool.connect();try{await client.query('BEGIN');const p=await client.query('SELECT id,name,cost FROM products WHERE id=$1 AND business_id=$2 AND active=true',[productId,bid]);if(!p.rowCount)throw new Error('Product not found');const recipe=await recipeRequirements(client,bid,Number(productId),Number(qty));const lid=await operationalStockLocation(client,bid,locationId||(recipe?.locationId||null)),ref=makeDocNo(consumptionType==='staff_meal'?'STM':'CMP');const h=await client.query('INSERT INTO inventory_consumptions(business_id,location_id,consumption_type,reference_no,notes,created_by) VALUES($1,$2,$3,$4,$5,$6) RETURNING *',[bid,lid,consumptionType,ref,notes,req.user.name]);if(recipe){for(const line of recipe.lines){const c=await client.query('SELECT avg_cost FROM inventory_balances WHERE location_id=$1 AND product_id=$2',[lid,line.ingredientProductId]);const unitCost=Number(c.rows[0]?.avg_cost||line.unitCost||0);await client.query('INSERT INTO inventory_consumption_items(consumption_id,product_id,qty,unit_cost) VALUES($1,$2,$3,$4)',[h.rows[0].id,line.ingredientProductId,line.qty,unitCost]);await inventoryBalanceChange(client,{bid,locationId:lid,productId:line.ingredientProductId,delta:-line.qty,unitCost,movementType:consumptionType,referenceType:'CONSUMPTION',referenceId:Number(h.rows[0].id),referenceNo:ref,notes,userName:req.user.name,fromLocationId:lid,reason:consumptionType})}}else{const c=await client.query('SELECT avg_cost FROM inventory_balances WHERE location_id=$1 AND product_id=$2',[lid,productId]),unitCost=Number(c.rows[0]?.avg_cost||p.rows[0].cost||0);await client.query('INSERT INTO inventory_consumption_items(consumption_id,product_id,qty,unit_cost) VALUES($1,$2,$3,$4)',[h.rows[0].id,productId,Number(qty),unitCost]);await inventoryBalanceChange(client,{bid,locationId:lid,productId:Number(productId),delta:-Number(qty),unitCost,movementType:consumptionType,referenceType:'CONSUMPTION',referenceId:Number(h.rows[0].id),referenceNo:ref,notes,userName:req.user.name,fromLocationId:lid,reason:consumptionType})}await client.query('COMMIT');await audit(req.user,bid,'post','inventory_consumption',h.rows[0].id,{referenceNo:ref,consumptionType});res.json(h.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

app.get('/api/inventory/overview',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const q=await Promise.all([
  pool.query('SELECT count(*)::int v FROM inventory_locations WHERE business_id=$1 AND active=true',[bid]),
  pool.query('SELECT coalesce(sum(ib.qty*ib.avg_cost),0)::numeric v FROM inventory_balances ib WHERE ib.business_id=$1',[bid]),
  pool.query('SELECT count(*)::int v FROM products WHERE business_id=$1 AND stock<=reorder_level AND active=true',[bid]),
  pool.query("SELECT count(*)::int v FROM stock_counts WHERE business_id=$1 AND status='draft'",[bid])
]);res.json({locations:q[0].rows[0].v,stockValue:q[1].rows[0].v,lowStock:q[2].rows[0].v,openCounts:q[3].rows[0].v})});
app.get('/api/inventory/locations',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const q=await pool.query("SELECT l.*,b.name branch_name,coalesce(sum(ib.qty),0)::numeric total_units,coalesce(sum(ib.qty*ib.avg_cost),0)::numeric stock_value FROM inventory_locations l JOIN branches b ON b.id=l.branch_id LEFT JOIN inventory_balances ib ON ib.location_id=l.id WHERE l.business_id=$1 GROUP BY l.id,b.name ORDER BY b.id,l.is_default DESC,l.name",[bid]);res.json(q.rows)});
app.post('/api/inventory/locations',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const {branchId,name,locationType='store'}=req.body||{};if(!branchId||!name?.trim())return res.status(400).json({error:'Branch and location name are required'});const b=await pool.query('SELECT id FROM branches WHERE id=$1 AND business_id=$2 AND active=true',[branchId,bid]);if(!b.rowCount)return res.status(400).json({error:'Branch not found'});try{const q=await pool.query('INSERT INTO inventory_locations(business_id,branch_id,name,location_type) VALUES($1,$2,$3,$4) RETURNING *',[bid,branchId,name.trim(),locationType||'store']);await audit(req.user,bid,'create','inventory_location',q.rows[0].id,{name:q.rows[0].name});res.json(q.rows[0])}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/inventory/balances',auth,tenant,async(req,res)=>{const bid=await getBiz(req),locationId=Number(req.query.locationId||0);const p=[bid];let where='ib.business_id=$1';if(locationId){p.push(locationId);where+=' AND ib.location_id=$2'}const q=await pool.query("SELECT ib.*,p.name product_name,p.sku,p.reorder_level,l.name location_name,b.name branch_name FROM inventory_balances ib JOIN products p ON p.id=ib.product_id JOIN inventory_locations l ON l.id=ib.location_id JOIN branches b ON b.id=l.branch_id WHERE "+where+" ORDER BY b.name,l.name,p.name",p);res.json(q.rows)});
app.post('/api/inventory/adjustments',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const {locationId,adjustmentType='adjustment',reason=null,items=[]}=req.body||{};if(!locationId||!Array.isArray(items)||!items.length)return res.status(400).json({error:'Location and at least one item are required'});const clean=items.map(x=>({productId:Number(x.productId),qtyChange:Number(x.qtyChange),unitCost:Number(x.unitCost||0)})).filter(x=>x.productId&&x.qtyChange!==0);if(clean.length!==items.length)return res.status(400).json({error:'Each adjustment needs a product and non-zero quantity change'});if(['wastage','spoilage'].includes(adjustmentType)&&clean.some(x=>x.qtyChange>0))return res.status(400).json({error:'Wastage and spoilage quantities must reduce stock'});const client=await pool.connect();try{await client.query('BEGIN');const loc=await client.query('SELECT id,name FROM inventory_locations WHERE id=$1 AND business_id=$2 AND active=true',[locationId,bid]);if(!loc.rowCount)throw new Error('Inventory location not found');const needsApproval=['wastage','spoilage'].includes(adjustmentType),ref=makeDocNo(adjustmentType==='wastage'?'WST':adjustmentType==='spoilage'?'SPL':'ADJ');const h=await client.query("INSERT INTO stock_adjustments(business_id,location_id,reference_no,adjustment_type,reason,created_by,requested_by,status) VALUES($1,$2,$3,$4,$5,$6,$6,$7) RETURNING *",[bid,locationId,ref,adjustmentType,reason,req.user.name,needsApproval?'pending_approval':'posted']);for(const x of clean)await client.query('INSERT INTO stock_adjustment_items(adjustment_id,product_id,qty_change,unit_cost) VALUES($1,$2,$3,$4)',[h.rows[0].id,x.productId,x.qtyChange,x.unitCost]);if(needsApproval){const actionType=adjustmentType==='wastage'?'inventory_wastage':'inventory_spoilage',target=await approvalTarget(client,bid,actionType);const total=clean.reduce((n,x)=>n+Math.abs(x.qtyChange*x.unitCost),0);const ar=await client.query("INSERT INTO approval_requests(business_id,section,action_type,entity_type,entity_id,reference_no,title,amount,requested_by_user_id,requested_by_name,approver_user_id,approver_role,status,request_comment) VALUES($1,'Inventory',$2,'stock_adjustment',$3,$4,$5,$6,$7,$8,$9,$10,'pending',$11) RETURNING *",[bid,actionType,h.rows[0].id,ref,(adjustmentType==='wastage'?'Wastage ':'Spoilage ')+ref+' · '+loc.rows[0].name,total,req.user.id,req.user.name,target.approverUserId,target.approverRole,reason]);await client.query('COMMIT');await audit(req.user,bid,'request_approval','stock_adjustment',h.rows[0].id,{referenceNo:ref,approvalRequestId:ar.rows[0].id,adjustmentType});return res.json({adjustment:h.rows[0],approval:ar.rows[0],pendingApproval:true})}for(const x of clean)await inventoryBalanceChange(client,{bid,locationId:Number(locationId),productId:x.productId,delta:x.qtyChange,unitCost:x.unitCost,movementType:adjustmentType,referenceType:'ADJUSTMENT',referenceId:Number(h.rows[0].id),referenceNo:ref,notes:reason,userName:req.user.name,fromLocationId:x.qtyChange<0?Number(locationId):null,toLocationId:x.qtyChange>0?Number(locationId):null,reason});await client.query('COMMIT');await audit(req.user,bid,'post','stock_adjustment',h.rows[0].id,{referenceNo:ref,adjustmentType});res.json(h.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/inventory/transfers',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const q=await pool.query("SELECT t.*,f.name from_location,tol.name to_location,coalesce(sum(i.qty),0)::numeric total_qty FROM stock_transfers t JOIN inventory_locations f ON f.id=t.from_location_id JOIN inventory_locations tol ON tol.id=t.to_location_id LEFT JOIN stock_transfer_items i ON i.transfer_id=t.id WHERE t.business_id=$1 GROUP BY t.id,f.name,tol.name ORDER BY t.id DESC LIMIT 200",[bid]);res.json(q.rows)});
