app.post('/api/inventory/counts/:id/post',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),items=Array.isArray(req.body?.items)?req.body.items:[];const client=await pool.connect();try{await client.query('BEGIN');const h=await client.query("SELECT * FROM stock_counts WHERE id=$1 AND business_id=$2 FOR UPDATE",[id,bid]);if(!h.rowCount)throw new Error('Stock count not found');if(h.rows[0].status!=='draft')throw new Error('Only draft stock counts can be posted');const existing=await client.query('SELECT * FROM stock_count_items WHERE stock_count_id=$1 ORDER BY id',[id]);const input=new Map(items.map(x=>[Number(x.itemId),Number(x.countedQty)]));for(const row of existing.rows){if(!input.has(Number(row.id))||!Number.isFinite(input.get(Number(row.id))))throw new Error('Every stock count item needs a counted quantity');const counted=input.get(Number(row.id));if(counted<0)throw new Error('Counted quantity cannot be negative');const diff=counted-Number(row.expected_qty);await client.query('UPDATE stock_count_items SET counted_qty=$1 WHERE id=$2',[counted,row.id]);if(Math.abs(diff)>0.000001)await inventoryBalanceChange(client,{bid,locationId:Number(h.rows[0].location_id),productId:Number(row.product_id),delta:diff,movementType:'count_adjustment',referenceType:'STOCK_COUNT',referenceId:id,referenceNo:h.rows[0].reference_no,notes:h.rows[0].notes,userName:req.user.name,fromLocationId:diff<0?Number(h.rows[0].location_id):null,toLocationId:diff>0?Number(h.rows[0].location_id):null,reason:'Physical stock count'})}await client.query("UPDATE stock_counts SET status='posted',posted_at=now() WHERE id=$1",[id]);await client.query('COMMIT');await audit(req.user,bid,'post','stock_count',id,{referenceNo:h.rows[0].reference_no});res.json({ok:true,id,status:'posted'})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});




app.post('/api/transaction-adjustments/request',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const {sourceType,sourceId=null,adjustmentType,baseAmount=0,requestedAmount=0,requestedPercent=0,reason,urgent=false}=req.body||{};if(!['restaurant_order','pos_draft'].includes(sourceType))return res.status(400).json({error:'Invalid adjustment source'});if(!['discount','foc'].includes(adjustmentType))return res.status(400).json({error:'Invalid adjustment type'});if(!String(reason||'').trim())return res.status(400).json({error:'Reason is required'});const client=await pool.connect();try{await client.query('BEGIN');let base=Number(baseAmount||0),sid=sourceId?Number(sourceId):null,ref;if(sourceType==='restaurant_order'){const o=await client.query("SELECT * FROM restaurant_orders WHERE id=$1 AND business_id=$2 AND status NOT IN ('bill_requested','partially_paid','paid','closed','cancelled') FOR UPDATE",[sid,bid]);if(!o.rowCount)throw new Error('Restaurant order is not eligible for adjustments');base=Number(o.rows[0].subtotal||0);ref=o.rows[0].order_no}else{if(!(base>0))throw new Error('POS draft subtotal is required');ref=makeDocNo('POS')}let amount=adjustmentType==='foc'?base:Number(requestedAmount||0);const pct=Number(requestedPercent||0);if(adjustmentType==='discount'&&pct>0)amount=base*pct/100;if(!(amount>0))throw new Error('Discount amount must be positive');if(amount>base+0.005)throw new Error('Discount cannot exceed the transaction subtotal');if(sourceType==='restaurant_order'){const oq=await client.query('SELECT amount_paid,total,service_charge,tax,tip,tax_inclusive FROM restaurant_orders WHERE id=$1',[sid]);const current=oq.rows[0],projected=Math.max(0,base-amount+Number(current.service_charge||0)+Number(current.tip||0)+(current.tax_inclusive?0:Number(current.tax||0)));if(projected+0.005<Number(current.amount_paid||0))throw new Error('Adjustment would reduce the bill below money already paid. Refund or reverse the deposit first.')}const adjRef=makeDocNo(adjustmentType==='foc'?'FOC':'DISC');const tx=await client.query("INSERT INTO transaction_adjustment_requests(business_id,source_type,source_id,reference_no,adjustment_type,base_amount,requested_amount,requested_percent,reason,status,requested_by_user_id,requested_by_name) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9,'pending',$10,$11) RETURNING *",[bid,sourceType,sid,adjRef,adjustmentType,base,amount,pct,String(reason).trim(),req.user.id,req.user.name]);const action=adjustmentType==='foc'?'transaction_foc':'transaction_discount',target=await approvalTarget(client,bid,action),title=(adjustmentType==='foc'?'FOC Approval · ':'Discount Approval · ')+(ref||adjRef);const ar=await client.query("INSERT INTO approval_requests(business_id,section,action_type,entity_type,entity_id,reference_no,title,amount,requested_by_user_id,requested_by_name,approver_user_id,approver_role,status,request_comment,priority) VALUES($1,'Sales',$2,'transaction_adjustment',$3,$4,$5,$6,$7,$8,$9,$10,'pending',$11,$12) RETURNING *",[bid,action,tx.rows[0].id,adjRef,title,amount,req.user.id,req.user.name,target.approverUserId,target.approverRole,String(reason).trim(),urgent?'urgent':'normal']);await client.query('COMMIT');await audit(req.user,bid,'request_approval','transaction_adjustment',tx.rows[0].id,{approvalRequestId:ar.rows[0].id,adjustmentType,sourceType,sourceId:sid,amount});res.json({adjustment:tx.rows[0],approval:ar.rows[0]})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

