app.post('/api/approvals/:id/approve',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),comment=req.body?.comment||null,client=await pool.connect();try{await client.query('BEGIN');const a=await client.query("SELECT * FROM approval_requests WHERE id=$1 AND business_id=$2 FOR UPDATE",[id,bid]);if(!a.rowCount)throw new Error('Approval request not found');const ar=a.rows[0];if(ar.status!=='pending')throw new Error('Approval request has already been decided');if(!(await canDecideApproval(client,req,bid,ar)))throw new Error('You are not the assigned approver');if(ar.action_type==='purchase_order'){const q=await client.query("UPDATE purchase_orders SET status='ordered',approval_status='approved',approval_comment=$1,approved_by=$2,approved_at=now(),ordered_at=coalesce(ordered_at,now()),updated_at=now() WHERE id=$3 AND business_id=$4 AND status='pending_approval' RETURNING *",[comment,req.user.name,ar.entity_id,bid]);if(!q.rowCount)throw new Error('Purchase order is no longer awaiting approval')}else if(ar.action_type==='restaurant_order_cancel'){const o=await client.query("SELECT * FROM restaurant_orders WHERE id=$1 AND business_id=$2 FOR UPDATE",[ar.entity_id,bid]);if(!o.rowCount||['closed','cancelled','paid'].includes(o.rows[0].status))throw new Error('Order is no longer cancellable');await client.query("UPDATE restaurant_orders SET status='cancelled',held=false,closed_at=now(),updated_at=now(),notes=concat(coalesce(notes,''),' | Cancelled: ',coalesce($1,'')) WHERE id=$2",[comment,ar.entity_id]);await client.query("INSERT INTO restaurant_order_status_history(order_id,from_status,to_status,comment,changed_by) VALUES($1,$2,'cancelled',$3,$4)",[ar.entity_id,o.rows[0].status,comment||ar.request_comment,req.user.name]);await freeRestaurantTableIfUnused(client,bid,o.rows[0].table_id,ar.entity_id)}else if(['transaction_discount','transaction_foc'].includes(ar.action_type)){const txq=await client.query("SELECT * FROM transaction_adjustment_requests WHERE id=$1 AND business_id=$2 FOR UPDATE",[ar.entity_id,bid]);if(!txq.rowCount||txq.rows[0].status!=='pending')throw new Error('Adjustment request is no longer pending');const tx=txq.rows[0];if(tx.source_type==='restaurant_order'){const oq=await client.query("SELECT * FROM restaurant_orders WHERE id=$1 AND business_id=$2 AND status NOT IN ('bill_requested','partially_paid','paid','closed','cancelled') FOR UPDATE",[tx.source_id,bid]);if(!oq.rowCount)throw new Error('Restaurant order is no longer eligible for this adjustment');const o=oq.rows[0],amount=tx.adjustment_type==='foc'?Number(o.subtotal):Math.min(Number(tx.requested_amount),Number(o.subtotal)),projected=Math.max(0,Number(o.subtotal)-amount+Number(o.service_charge||0)+Number(o.tip||0)+(o.tax_inclusive?0:Number(o.tax||0)));if(projected+0.005<Number(o.amount_paid||0))throw new Error('Approved adjustment would reduce the bill below money already paid');if(tx.adjustment_type==='foc')await client.query("UPDATE restaurant_orders SET discount=subtotal,tax=0,service_charge=0,tip=0,updated_at=now() WHERE id=$1",[o.id]);else await client.query("UPDATE restaurant_orders SET discount=$1,updated_at=now() WHERE id=$2",[amount,o.id]);await recalcRestaurantOrder(client,o.id);await client.query("UPDATE transaction_adjustment_requests SET status='approved',approved_by_user_id=$1,approved_by_name=$2,approved_at=now(),decision_comment=$3,consumed_at=now() WHERE id=$4",[req.user.id,req.user.name,comment,tx.id])}else{await client.query("UPDATE transaction_adjustment_requests SET status='approved',approved_by_user_id=$1,approved_by_name=$2,approved_at=now(),decision_comment=$3 WHERE id=$4",[req.user.id,req.user.name,comment,tx.id])}}else if(['sale_refund','sale_void'].includes(ar.action_type)){await executeRefundApproval(client,req,bid,ar.entity_id,comment)}else if(['inventory_wastage','inventory_spoilage'].includes(ar.action_type)){const h=await client.query("SELECT * FROM stock_adjustments WHERE id=$1 AND business_id=$2 FOR UPDATE",[ar.entity_id,bid]);if(!h.rowCount||h.rows[0].status!=='pending_approval')throw new Error('Stock adjustment is no longer awaiting approval');const items=await client.query('SELECT * FROM stock_adjustment_items WHERE adjustment_id=$1 ORDER BY id',[ar.entity_id]);for(const x of items.rows)await inventoryBalanceChange(client,{bid,locationId:Number(h.rows[0].location_id),productId:Number(x.product_id),delta:Number(x.qty_change),unitCost:Number(x.unit_cost||0),movementType:h.rows[0].adjustment_type,referenceType:'ADJUSTMENT',referenceId:Number(h.rows[0].id),referenceNo:h.rows[0].reference_no,notes:h.rows[0].reason,userName:req.user.name,fromLocationId:Number(x.qty_change)<0?Number(h.rows[0].location_id):null,toLocationId:Number(x.qty_change)>0?Number(h.rows[0].location_id):null,reason:h.rows[0].reason});await client.query("UPDATE stock_adjustments SET status='posted',decision_comment=$1,approved_by=$2,approved_at=now() WHERE id=$3",[comment,req.user.name,ar.entity_id])}else throw new Error('Approval action is not yet executable');await client.query("UPDATE approval_requests SET status='approved',decision_comment=$1,decided_by_user_id=$2,decided_by_name=$3,decided_at=now() WHERE id=$4",[comment,req.user.id,req.user.name,id]);await client.query('COMMIT');await audit(req.user,bid,'approve','approval_request',id,{actionType:ar.action_type,entityId:ar.entity_id,comment});res.json({ok:true,status:'approved'})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.post('/api/approvals/:id/reject',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),comment=String(req.body?.comment||'').trim();if(!comment)return res.status(400).json({error:'Rejection comment is required'});const client=await pool.connect();try{await client.query('BEGIN');const a=await client.query("SELECT * FROM approval_requests WHERE id=$1 AND business_id=$2 FOR UPDATE",[id,bid]);if(!a.rowCount)throw new Error('Approval request not found');const ar=a.rows[0];if(ar.status!=='pending')throw new Error('Approval request has already been decided');if(!(await canDecideApproval(client,req,bid,ar)))return res.status(403).json({error:'You are not the assigned approver'});if(ar.action_type==='purchase_order')await client.query("UPDATE purchase_orders SET status='rejected',approval_status='rejected',approval_comment=$1,rejected_by=$2,rejected_at=now(),updated_at=now() WHERE id=$3 AND business_id=$4",[comment,req.user.name,ar.entity_id,bid]);else if(['inventory_wastage','inventory_spoilage'].includes(ar.action_type))await client.query("UPDATE stock_adjustments SET status='rejected',decision_comment=$1,rejected_by=$2,rejected_at=now() WHERE id=$3 AND business_id=$4",[comment,req.user.name,ar.entity_id,bid]);else if(['transaction_discount','transaction_foc'].includes(ar.action_type))await client.query("UPDATE transaction_adjustment_requests SET status='rejected',rejected_by_user_id=$1,rejected_by_name=$2,rejected_at=now(),decision_comment=$3 WHERE id=$4 AND business_id=$5",[req.user.id,req.user.name,comment,ar.entity_id,bid]);else if(['sale_refund','sale_void'].includes(ar.action_type))await client.query("UPDATE refunds SET status='rejected',rejected_by_user_id=$1,rejected_by_name=$2,rejected_at=now(),decision_comment=$3 WHERE id=$4 AND business_id=$5",[req.user.id,req.user.name,comment,ar.entity_id,bid]);await client.query("UPDATE approval_requests SET status='rejected',decision_comment=$1,decided_by_user_id=$2,decided_by_name=$3,decided_at=now() WHERE id=$4",[comment,req.user.id,req.user.name,id]);await client.query('COMMIT');await audit(req.user,bid,'reject','approval_request',id,{actionType:ar.action_type,entityId:ar.entity_id,comment});res.json({ok:true,status:'rejected'})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

app.get('/api/document-settings',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const q=await pool.query('SELECT id,name,country,currency,address,phone,email,tax_id,logo_url,document_footer,document_accent,document_paper_size,default_tax_rate,tax_inclusive,default_service_charge_rate,receipt_title,receipt_payment_options,receipt_header_note,receipt_show_logo,receipt_show_business_name,theme_key,theme_mode FROM businesses WHERE id=$1',[bid]);res.json(q.rows[0]||{})});
app.post('/api/document-settings/logo',auth,tenant,permit('settings.manage'),brandingUpload.single('image'),async(req,res)=>{const bid=await getBiz(req);if(!req.file)return res.status(400).json({error:'Choose a PNG, JPG or WebP logo under 5MB'});const url='/uploads/branding/'+req.file.filename;const q=await pool.query('UPDATE businesses SET logo_url=$1 WHERE id=$2 RETURNING logo_url',[url,bid]);await audit(req.user,bid,'upload_logo','business',bid,{logoUrl:url});res.json({ok:true,logoUrl:q.rows[0].logo_url})});
app.put('/api/document-settings',auth,tenant,permit('settings.manage'),async(req,res)=>{const bid=await getBiz(req);const {name=null,address=null,phone=null,email=null,taxId=null,logoUrl=null,documentFooter=null,documentAccent='#101828',documentPaperSize='A4',defaultTaxRate=0,taxInclusive=false,defaultServiceChargeRate=0,receiptTitle='ORDER BILL',receiptPaymentOptions='CASH | MTN MOMO | AIRTEL MONEY | CARD',receiptHeaderNote=null,receiptShowLogo=true,receiptShowBusinessName=false,themeKey='green',themeMode='light'}=req.body||{};const q=await pool.query("UPDATE businesses SET name=coalesce(nullif(trim($1),''),name),address=$2,phone=$3,email=$4,tax_id=$5,logo_url=$6,document_footer=$7,document_accent=$8,document_paper_size=CASE WHEN $9 IN ('58mm','80mm','A4','A5') THEN $9 ELSE 'A4' END,default_tax_rate=$10,tax_inclusive=$11,default_service_charge_rate=$12,receipt_title=$13,receipt_payment_options=$14,receipt_header_note=$15,receipt_show_logo=$16,receipt_show_business_name=$17,theme_key=$18,theme_mode=$19 WHERE id=$20 RETURNING id,name,country,currency,address,phone,email,tax_id,logo_url,document_footer,document_accent,document_paper_size,default_tax_rate,tax_inclusive,default_service_charge_rate,receipt_title,receipt_payment_options,receipt_header_note,receipt_show_logo,receipt_show_business_name,theme_key,theme_mode",[name,address,phone,email,taxId,logoUrl,documentFooter,documentAccent,documentPaperSize,Math.max(0,Number(defaultTaxRate||0)),!!taxInclusive,Math.max(0,Number(defaultServiceChargeRate||0)),String(receiptTitle||'ORDER BILL').slice(0,80),String(receiptPaymentOptions||'').slice(0,300),receiptHeaderNote||null,!!receiptShowLogo,!!receiptShowBusinessName,String(themeKey||'green'),String(themeMode||'light'),bid]);await audit(req.user,bid,'update','document_settings',bid,{name});res.json(q.rows[0])});
function drawBusinessLogo(doc,biz,opts={}){const logo=String(biz.logo_url||''),local=logo.startsWith('/uploads/')?logo.replace(/^\/uploads\//,'uploads/'):null;try{if(local&&fs.existsSync(local)){doc.image(local,opts);return true}if(logo.startsWith('data:image/')&&logo.includes('base64,')){doc.image(Buffer.from(logo.split('base64,')[1],'base64'),opts);return true}}catch{}return false}
function pdfAccent(biz){const c=String(biz.document_accent||'#22A53A');return /^#[0-9a-f]{6}$/i.test(c)?c:'#22A53A'}
function pdfMoney(biz,n){return String(biz.currency||'')+' '+Number(n||0).toLocaleString(undefined,{maximumFractionDigits:2})}
function pdfHeader(doc,biz,title,number){
  const m=doc.page.margins.left||42,right=doc.page.width-(doc.page.margins.right||42),top=doc.page.margins.top||42,accent=pdfAccent(biz);
  const hadLogo=drawBusinessLogo(doc,biz,{fit:[105,56],x:m,y:top-4});
  if(!hadLogo)doc.font('Helvetica-Bold').fontSize(18).fillColor('#111827').text(biz.name||'Business',m,top,{width:260});else if(biz.receipt_show_business_name)doc.font('Helvetica-Bold').fontSize(9).fillColor('#334155').text(biz.name||'',m,top+58,{width:260});
  doc.font('Helvetica-Bold').fontSize(17).fillColor('#111827').text(title,m+290,top,{width:right-m-290,align:'right'});
  if(number)doc.font('Helvetica').fontSize(9).fillColor('#64748B').text(number,m+290,top+24,{width:right-m-290,align:'right'});
  const contact=[biz.address,biz.phone,biz.email,biz.tax_id?'TIN '+biz.tax_id:null].filter(Boolean).join('  •  ');
  if(contact)doc.font('Helvetica').fontSize(8).fillColor('#64748B').text(contact,m,top+66,{width:right-m});
  doc.moveTo(m,top+84).lineTo(right,top+84).lineWidth(2).strokeColor(accent).stroke();
  doc.y=top+98;doc.fillColor('#111827');
}
function pdfFooter(doc,biz){
  const m=doc.page.margins.left||42,right=doc.page.width-(doc.page.margins.right||42),y=doc.page.height-28;
  doc.moveTo(m,y-7).lineTo(right,y-7).lineWidth(.5).strokeColor('#E5E7EB').stroke();
  const text=String(biz.document_footer||'Powered by MauzoPOS');
  doc.font('Helvetica').fontSize(7.5).fillColor('#94A3B8').text(text,m,y,{width:right-m,align:'center'});
}
function pdfSectionTitle(doc,title,sub=''){
  const m=doc.page.margins.left||42,accent='#111827';
  doc.moveDown(.2).font('Helvetica-Bold').fontSize(11).fillColor(accent).text(title,m,doc.y);
  if(sub)doc.font('Helvetica').fontSize(7.5).fillColor('#94A3B8').text(sub,m,doc.y+2);
  doc.moveDown(.45);
}
function pdfMetaGrid(doc,items){
  const x=doc.page.margins.left||42,w=doc.page.width-x-(doc.page.margins.right||42),cols=3,gap=8,cw=(w-gap*(cols-1))/cols,startY=doc.y;
  items.filter(x=>x&&x[1]!==undefined&&x[1]!==null).forEach(([label,value],i)=>{
    const col=i%cols,row=Math.floor(i/cols),bx=x+col*(cw+gap),by=startY+row*42;
    doc.roundedRect(bx,by,cw,34,5).fill('#F8FAFC');
    doc.font('Helvetica').fontSize(7).fillColor('#94A3B8').text(String(label).toUpperCase(),bx+9,by+7,{width:cw-18});
    doc.font('Helvetica-Bold').fontSize(9).fillColor('#334155').text(String(value),bx+9,by+18,{width:cw-18,ellipsis:true});
  });
  const count=items.filter(x=>x&&x[1]!==undefined&&x[1]!==null).length;doc.y=startY+Math.ceil(count/cols)*42+4;
}
function pdfMetricCards(doc,biz,cards){
  const x=doc.page.margins.left||42,w=doc.page.width-x-(doc.page.margins.right||42),gap=8,cols=Math.min(4,cards.length||1),cw=(w-gap*(cols-1))/cols,startY=doc.y,accent=pdfAccent(biz);
  cards.forEach((card,i)=>{
    const col=i%cols,row=Math.floor(i/cols),bx=x+col*(cw+gap),by=startY+row*58;
    doc.roundedRect(bx,by,cw,50,6).fill(card.tone==='danger'?'#FEF2F2':card.tone==='warn'?'#FFF7ED':'#F8FAFC');
    doc.rect(bx,by,3,50).fill(card.tone==='danger'?'#DC2626':card.tone==='warn'?'#D97706':accent);
    doc.font('Helvetica').fontSize(7.2).fillColor('#64748B').text(String(card.label).toUpperCase(),bx+11,by+9,{width:cw-20});
    doc.font('Helvetica-Bold').fontSize(12).fillColor(card.tone==='danger'?'#B91C1C':'#0F172A').text(String(card.value),bx+11,by+23,{width:cw-20,ellipsis:true});
  });
  doc.y=startY+Math.ceil(cards.length/cols)*58+4;
}
function pdfTable(doc,biz,columns,rows,opts={}){
  const margin=doc.page.margins.left||30,right=doc.page.width-(doc.page.margins.right||30),totalW=right-margin,accent=pdfAccent(biz),fontSize=opts.fontSize||7.2;
  const weights=columns.map((c,i)=>{const s=String(c).toLowerCase();if(/description|product|customer|supplier|notes|reason/.test(s))return 1.8;if(/date|status|amount|total|price|cost|qty|shift/.test(s))return 1.05;return 1.2});
  const sum=weights.reduce((a,b)=>a+b,0),widths=weights.map(v=>totalW*v/sum);
  const drawHeader=()=>{
    const y=doc.y;doc.roundedRect(margin,y,totalW,24,4).fill(accent);
    let x=margin;columns.forEach((col,i)=>{doc.font('Helvetica-Bold').fontSize(6.8).fillColor('#FFFFFF').text(String(col).toUpperCase(),x+6,y+8,{width:widths[i]-12,ellipsis:true});x+=widths[i]});doc.y=y+28;
  };
  const ensure=(h=24)=>{if(doc.y+h>doc.page.height-(doc.page.margins.bottom||32)-24){pdfFooter(doc,biz);doc.addPage();pdfHeader(doc,biz,opts.title||'REPORT',opts.number||'');drawHeader()}};
  drawHeader();
  rows.forEach((row,ri)=>{
    ensure(26);const y=doc.y,rowH=24;
    if(ri%2===1)doc.rect(margin,y,totalW,rowH).fill('#F8FAFC');
    let x=margin;row.forEach((val,i)=>{const col=String(columns[i]||'').toLowerCase(),isMoney=/amount|total|discount|tax|cost|valuation|opening|expected|actual|variance|price/.test(col),txt=isMoney&&typeof val==='number'?pdfMoney(biz,val):String(val??'');doc.font('Helvetica').fontSize(fontSize).fillColor('#334155').text(txt,x+6,y+7,{width:widths[i]-12,ellipsis:true,align:isMoney?'right':'left'});x+=widths[i]});
    doc.moveTo(margin,y+rowH).lineTo(right,y+rowH).lineWidth(.3).strokeColor('#E5E7EB').stroke();doc.y=y+rowH;
  });
  doc.moveDown(.4);
}
function thermalWidth(paper){return paper==='58mm'?164:226}
function thermalChars(paper){return paper==='58mm'?30:42}
function thermalRule(paper,ch='-'){return ch.repeat(thermalChars(paper))}
function thermalPair(doc,paper,left,right,{bold=false,size=8}={}){
  const width=thermalWidth(paper)-20,rightW=paper==='58mm'?66:88,leftW=width-rightW;
  doc.font(bold?'Courier-Bold':'Courier').fontSize(size).fillColor('#111111')
    .text(String(left||''),10,doc.y,{width:leftW,continued:true})
    .text(String(right||''),{width:rightW,align:'right'});
}
function thermalReceiptHeader(doc,biz,title,number,meta=[],paper='80mm'){
  const width=thermalWidth(paper),logo=String(biz.logo_url||'');
  if(logo&&drawBusinessLogo(doc,biz,{fit:[paper==='58mm'?48:58,paper==='58mm'?38:44],align:'center'}))doc.moveDown(.15);
  if(!logo||biz.receipt_show_business_name)doc.font('Courier-Bold').fontSize(paper==='58mm'?9:10).fillColor('#111').text(String(biz.name||'BUSINESS').toUpperCase(),{align:'center'});
  const contact=[biz.address,biz.phone,biz.email].filter(Boolean).join(' | ');
  if(contact)doc.font('Courier').fontSize(paper==='58mm'?6.2:6.8).fillColor('#333').text(contact,{align:'center'});
  if(biz.tax_id)doc.font('Courier').fontSize(6.5).fillColor('#444').text('TIN: '+biz.tax_id,{align:'center'});
  doc.moveDown(.2).font('Courier').fontSize(7).fillColor('#111').text(thermalRule(paper,'='),{align:'center'});
  doc.font('Courier-Bold').fontSize(paper==='58mm'?10:11).text(String(title||biz.receipt_title||'RECEIPT').toUpperCase(),{align:'center'});
  if(number)doc.font('Courier-Bold').fontSize(8).text('# '+number,{align:'center'});
  if(biz.receipt_header_note)doc.font('Courier').fontSize(6.5).fillColor('#444').text(biz.receipt_header_note,{align:'center'});
  doc.moveDown(.15).font('Courier').fontSize(7).fillColor('#111').text(thermalRule(paper),{align:'center'});
  doc.font('Courier').fontSize(7).fillColor('#222');
  for(const line of meta.filter(Boolean))doc.text(String(line).toUpperCase());
  doc.text(thermalRule(paper),{align:'center'}).moveDown(.1);
}
function thermalItems(doc,biz,paper,items){
  const width=thermalWidth(paper)-20,qtyW=paper==='58mm'?24:28,totalW=paper==='58mm'?52:62,nameW=width-qtyW-totalW;
  doc.font('Courier-Bold').fontSize(paper==='58mm'?6.7:7.3).fillColor('#111')
    .text('ITEM',10,doc.y,{width:nameW,continued:true})
    .text('QTY',{width:qtyW,continued:true,align:'right'})
    .text('TOTAL',{width:totalW,align:'right'});
  doc.font('Courier').fontSize(7).text(thermalRule(paper),{align:'center'});
  for(const i of items){
    const name=String(i.product_name||i.name||'ITEM').toUpperCase();
    const qty=Number(i.qty||0),total=Number(i.line_total??i.total??0);
    doc.font('Courier-Bold').fontSize(paper==='58mm'?7.2:7.8).text(name,10,doc.y,{width:nameW});
    doc.font('Courier').fontSize(paper==='58mm'?6.8:7.2)
      .text('',10,doc.y,{width:nameW,continued:true})
      .text(qty%1===0?String(qty):qty.toFixed(2),{width:qtyW,continued:true,align:'right'})
      .text(Number(total).toLocaleString(),{width:totalW,align:'right'});
    if(i.notes)doc.font('Courier-Oblique').fontSize(6.4).fillColor('#555').text('  '+String(i.notes),10,doc.y,{width:width-4});
    doc.moveDown(.08);
  }
  doc.font('Courier').fontSize(7).fillColor('#111').text(thermalRule(paper),{align:'center'});
}
function thermalTotals(doc,biz,paper,rows,totalLabel,total){
  for(const [label,value] of rows){if(Math.abs(Number(value||0))<.0001)continue;thermalPair(doc,paper,String(label).toUpperCase(),Number(value).toLocaleString(),{size:7.4})}
  doc.font('Courier').fontSize(7).text(thermalRule(paper,'='),{align:'center'});
  thermalPair(doc,paper,String(totalLabel).toUpperCase(),String(biz.currency||'')+' '+Number(total||0).toLocaleString(),{bold:true,size:paper==='58mm'?9:10});
  doc.font('Courier').fontSize(7).text(thermalRule(paper,'='),{align:'center'});
}
function thermalFooter(doc,biz,paper){
  if(biz.receipt_payment_options){doc.moveDown(.2).font('Courier-Bold').fontSize(6.7).text('PAYMENT OPTIONS',{align:'center'});doc.font('Courier').fontSize(6.3).fillColor('#333').text(String(biz.receipt_payment_options),{align:'center'});}
  if(biz.document_footer)doc.moveDown(.35).font('Courier').fontSize(6.4).fillColor('#555').text(String(biz.document_footer),{align:'center'});
  doc.moveDown(.2).font('Courier').fontSize(5.8).fillColor('#999').text('Powered by MauzoPOS',{align:'center'});
}
function thermalPageHeight(itemCount=1,extraLines=0,paper='80mm'){
  const base=paper==='58mm'?330:350,row=paper==='58mm'?25:23;
  return Math.max(base,Math.min(1500,base+Math.max(0,itemCount-1)*row+extraLines*12));
}
function thermalKotHeader(doc,biz,x,paper='80mm'){
  const logo=String(biz.logo_url||'');
  if(logo&&drawBusinessLogo(doc,biz,{fit:[48,34],align:'center'}))doc.moveDown(.1);
  doc.font('Courier-Bold').fontSize(13).fillColor('#111').text('KITCHEN ORDER TICKET',{align:'center'});
  doc.font('Courier-Bold').fontSize(9).text('# '+x.ticket_no,{align:'center'});
  doc.font('Courier').fontSize(7).text(thermalRule(paper,'='),{align:'center'});
  doc.font('Courier-Bold').fontSize(8).text('STATION: '+String(x.station_name||'KITCHEN').toUpperCase());
  doc.text('ORDER:   '+String(x.order_no||'').toUpperCase());
  if(x.table_name)doc.fontSize(10).text('TABLE:   '+String(x.table_name).toUpperCase());
  doc.font('Courier').fontSize(7).text('TIME:    '+new Date().toLocaleString());
  doc.text(thermalRule(paper,'='),{align:'center'});
}

