async function recordPrint(bid,user,documentType,entityType,entityId,documentNo,paperSize){
  const prev=await pool.query('SELECT 1 FROM print_logs WHERE business_id=$1 AND document_type=$2 AND entity_type=$3 AND entity_id=$4 LIMIT 1',[bid,documentType,entityType,entityId]);
  await pool.query('INSERT INTO print_logs(business_id,document_type,entity_type,entity_id,document_no,paper_size,printed_by,reprint) VALUES($1,$2,$3,$4,$5,$6,$7,$8)',[bid,documentType,entityType,entityId,documentNo||null,paperSize||null,user||null,prev.rowCount>0]);
}
