  if(type==='restaurant'){const q=await pool.query("SELECT ro.opened_at::date d,ro.order_no,ro.order_type,coalesce(rt.name,'-') table_name,ro.guest_count,ro.total,ro.status,ro.waiter_name FROM restaurant_orders ro LEFT JOIN restaurant_tables rt ON rt.id=ro.table_id WHERE ro.business_id=$1 AND ($2::date IS NULL OR ro.opened_at >= $2::date) AND ($3::date IS NULL OR ro.opened_at < $3::date+interval '1 day') AND ($4::bigint IS NULL OR ro.branch_id=$4) ORDER BY ro.opened_at DESC",params);return {title:'Restaurant Operations',columns:['Date','Order','Type','Table','Guests','Total','Status','Waiter'],rows:q.rows.map(x=>[String(x.d).slice(0,10),x.order_no,x.order_type,x.table_name,Number(x.guest_count||0),Number(x.total),x.status,x.waiter_name||''])}}
  if(type==='inventory'){const q=await pool.query("SELECT p.sku,p.name,p.category,coalesce(sum(ib.qty),p.stock) qty,coalesce(max(ib.avg_cost),p.cost) avg_cost,coalesce(sum(ib.qty),p.stock)*coalesce(max(ib.avg_cost),p.cost) valuation FROM products p LEFT JOIN inventory_balances ib ON ib.product_id=p.id AND ib.business_id=p.business_id WHERE p.business_id=$1 GROUP BY p.id ORDER BY p.name",[bid]);return {title:'Inventory Valuation',columns:['SKU','Product','Category','Qty','Average Cost','Valuation'],rows:q.rows.map(x=>[x.sku||'',x.name,x.category,Number(x.qty),Number(x.avg_cost),Number(x.valuation)])}}
  if(type==='cash'){const q=await pool.query("SELECT opened_at::date d,id,opened_by,opening_cash,expected_cash,closing_cash,variance,status FROM cash_sessions WHERE business_id=$1 AND ($2::date IS NULL OR opened_at >= $2::date) AND ($3::date IS NULL OR opened_at < $3::date+interval '1 day') AND ($4::bigint IS NULL OR branch_id=$4) ORDER BY id DESC",params);return {title:'Cash & Shift Reconciliation',columns:['Date','Shift','Opened By','Opening','Expected','Actual','Variance','Status'],rows:q.rows.map(x=>[String(x.d).slice(0,10),x.id,x.opened_by,Number(x.opening_cash),Number(x.expected_cash||0),Number(x.closing_cash||0),Number(x.variance||0),x.status])}}
  const [sales,exp,pay]=await Promise.all([pool.query("SELECT coalesce(sum(total),0) total,coalesce(sum(total-discount-tax),0) net FROM sales WHERE business_id=$1 AND ($2::date IS NULL OR created_at >= $2::date) AND ($3::date IS NULL OR created_at < $3::date+interval '1 day')",[bid,from||null,to||null]),pool.query("SELECT coalesce(sum(amount),0) total FROM expenses WHERE business_id=$1 AND status='posted' AND ($2::date IS NULL OR expense_date >= $2::date) AND ($3::date IS NULL OR expense_date <= $3::date)",[bid,from||null,to||null]),pool.query("SELECT payment_method,coalesce(sum(amount),0) total FROM payments WHERE business_id=$1 AND status='posted' AND ($2::date IS NULL OR received_at >= $2::date) AND ($3::date IS NULL OR received_at < $3::date+interval '1 day') GROUP BY payment_method ORDER BY payment_method",[bid,from||null,to||null])]);const gross=Number(sales.rows[0].total),expenses=Number(exp.rows[0].total);return {title:'Financial Summary',columns:['Metric','Amount'],rows:[['Gross Sales',gross],['Expenses',expenses],['Net After Expenses',gross-expenses],...pay.rows.map(x=>['Payments · '+niceText(x.payment_method),Number(x.total)])]}
