app.get('/api/reports/export',auth,tenant,permit('reports.export'),async(req,res)=>{const bid=await getBiz(req),type=String(req.query.report||'financial'),format=String(req.query.format||'xlsx'),from=req.query.from||null,to=req.query.to||null,branchId=req.query.branchId?Number(req.query.branchId):null,r=await buildManagementReport(bid,type,from,to,branchId),biz=(await pool.query('SELECT * FROM businesses WHERE id=$1',[bid])).rows[0],branchName=branchId?(await pool.query('SELECT name FROM branches WHERE id=$1 AND business_id=$2',[branchId,bid])).rows[0]?.name:'All branches';const filename='MauzoPOS-'+type+'-'+new Date().toISOString().slice(0,10);if(format==='csv'){res.setHeader('Content-Type','text/csv');res.setHeader('Content-Disposition','attachment; filename="'+filename+'.csv"');const esc=v=>'"'+String(v??'').replaceAll('"','""')+'"';return res.send([r.columns.map(esc).join(','),...r.rows.map(row=>row.map(esc).join(','))].join('\n'))}if(format==='pdf'){res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition','inline; filename="'+filename+'.pdf"');const doc=new PDFDocument({size:'A4',layout:'landscape',margin:30,info:{Title:r.title,Author:biz.name||'MauzoPOS'}});doc.pipe(res);pdfHeader(doc,biz,r.title.toUpperCase(),'REPORT · '+new Date().toISOString().slice(0,10));pdfMetaGrid(doc,[['Period',(from||'Beginning')+' — '+(to||'Today')],['Branch',branchName],['Generated',new Date().toLocaleString()],['Rows',r.rows.length],['Currency',biz.currency],['Prepared by',req.user.name||req.user.email||'User']]);pdfSectionTitle(doc,'Report Detail',r.rows.length+' record'+(r.rows.length===1?'':'s'));pdfTable(doc,biz,r.columns,r.rows.slice(0,700),{title:r.title.toUpperCase(),number:'REPORT'});if(r.rows.length>700){doc.moveDown().font('Helvetica-Oblique').fontSize(8).fillColor('#94A3B8').text('PDF preview limited to the first 700 rows. Use XLSX for the complete dataset.')}pdfFooter(doc,biz);doc.end();return}const wb=new ExcelJS.Workbook();wb.creator='MauzoPOS';wb.created=new Date();const ws=wb.addWorksheet(r.title.slice(0,31));ws.addRow([biz.name]);ws.addRow([r.title]);ws.addRow(['Period',from||'All',to||'All']);ws.addRow(['Branch',branchName]);ws.addRow(['Generated',new Date().toLocaleString()]);ws.addRow([]);ws.addRow(r.columns);for(const row of r.rows)ws.addRow(row);ws.mergeCells('A1:'+String.fromCharCode(64+Math.min(r.columns.length,26))+'1');ws.getRow(1).font={bold:true,size:16};ws.getRow(2).font={bold:true,size:13};ws.getRow(7).font={bold:true};ws.getRow(7).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFE8F5E9'}};ws.views=[{state:'frozen',ySplit:7}];ws.autoFilter={from:{row:7,column:1},to:{row:7,column:r.columns.length}};const moneyWords=['amount','total','discount','tax','cost','valuation','tendered','change','opening','expected','actual','variance','price'];ws.columns=r.columns.map((name,i)=>{const col={width:Math.min(30,Math.max(12,...r.rows.slice(0,100).map(x=>String(x[i]??'').length+2)))};return col});r.columns.forEach((name,i)=>{if(moneyWords.some(w=>String(name).toLowerCase().includes(w))){ws.getColumn(i+1).numFmt='#,##0.00'}});ws.eachRow((row,rowNo)=>{if(rowNo>7)row.alignment={vertical:'top'}});const meta=wb.addWorksheet('Report Info');meta.addRows([['Business',biz.name],['Report',r.title],['Currency',biz.currency],['From',from||'All'],['To',to||'All'],['Branch',branchName],['Generated',new Date().toISOString()]]);meta.getColumn(1).font={bold:true};meta.columns=[{width:18},{width:42}];res.setHeader('Content-Type','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');res.setHeader('Content-Disposition','attachment; filename="'+filename+'.xlsx"');await wb.xlsx.write(res);res.end()});

