app.post('/api/cash/open',auth,tenant,async(req,res)=>{const bid=await getBiz(req),opening=Math.max(0,Number(req.body?.openingCash||0)),branchId=Number(req.body?.branchId||0)||null,terminalId=Number(req.body?.terminalId||0)||null;if(!branchId)return res.status(400).json({error:'Choose a branch before opening the shift'});const client=await pool.connect();try{await client.query('BEGIN');const branch=await client.query('SELECT id FROM branches WHERE id=$1 AND business_id=$2 AND active=true',[branchId,bid]);if(!branch.rowCount)throw new Error('Branch is not available');const assigned=await client.query('SELECT branch_id FROM user_branch_assignments WHERE business_id=$1 AND user_id=$2',[bid,req.user.id]);if(assigned.rowCount&&!assigned.rows.some(x=>Number(x.branch_id)===Number(branchId)))throw new Error('You are not assigned to this branch');if(terminalId){const terminal=await client.query('SELECT id FROM terminals WHERE id=$1 AND business_id=$2 AND branch_id=$3 AND active=true',[terminalId,bid,branchId]);if(!terminal.rowCount)throw new Error('Terminal does not belong to the selected branch')}const own=await client.query("SELECT id FROM cash_sessions WHERE business_id=$1 AND status='open' AND opened_by_user_id=$2 FOR UPDATE",[bid,req.user.id]);if(own.rowCount)throw new Error('You already have an open shift');if(terminalId){const used=await client.query("SELECT id FROM cash_sessions WHERE business_id=$1 AND status='open' AND terminal_id=$2 FOR UPDATE",[bid,terminalId]);if(used.rowCount)throw new Error('This terminal already has an open shift')}const shiftNo='SHF-'+new Date().toISOString().slice(0,10).replaceAll('-','')+'-'+crypto.randomBytes(3).toString('hex').toUpperCase();const q=await client.query("INSERT INTO cash_sessions(business_id,branch_id,terminal_id,opened_by_user_id,opened_by,opening_cash,status,shift_no) VALUES($1,$2,$3,$4,$5,$6,'open',$7) RETURNING *",[bid,branchId,terminalId,req.user.id,req.user.name,opening,shiftNo]);await client.query('COMMIT');await audit(req.user,bid,'open','cash_shift',q.rows[0].id,{shiftNo,branchId,terminalId,openingCash:opening});res.json(q.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

async function shiftSnapshot(bid,sessionId){const q=await pool.query("SELECT cs.*,b.name branch_name,t.name terminal_name FROM cash_sessions cs LEFT JOIN branches b ON b.id=cs.branch_id LEFT JOIN terminals t ON t.id=cs.terminal_id WHERE cs.id=$1 AND cs.business_id=$2",[sessionId,bid]);if(!q.rowCount)return null;const x=q.rows[0];const [cashSales,refunds,moves,tenders]=await Promise.all([pool.query("SELECT coalesce(sum(amount),0)::numeric x FROM payments WHERE business_id=$1 AND cash_session_id=$2 AND status='posted' AND payment_method='cash'",[bid,x.id]),pool.query("SELECT coalesce(sum(rt.amount),0)::numeric x FROM refund_tenders rt JOIN refunds r ON r.id=rt.refund_id WHERE r.business_id=$1 AND r.status='approved' AND rt.cash_session_id=$2 AND rt.payment_method='cash'",[bid,x.id]),pool.query("SELECT coalesce(sum(CASE WHEN movement_type='cash_in' THEN amount ELSE -amount END),0)::numeric net,coalesce(sum(CASE WHEN movement_type='cash_in' THEN amount ELSE 0 END),0)::numeric cash_in,coalesce(sum(CASE WHEN movement_type='cash_out' THEN amount ELSE 0 END),0)::numeric cash_out FROM cash_movements WHERE session_id=$1",[x.id]),pool.query("SELECT payment_method,count(*)::int transactions,coalesce(sum(amount),0)::numeric total FROM payments WHERE business_id=$1 AND cash_session_id=$2 AND status='posted' GROUP BY payment_method ORDER BY payment_method",[bid,x.id])]);const expected=Number(x.opening_cash)+Number(cashSales.rows[0].x)-Number(refunds.rows[0].x)+Number(moves.rows[0].net);return {...x,cashSales:Number(cashSales.rows[0].x),refunds:Number(refunds.rows[0].x),cashIn:Number(moves.rows[0].cash_in),cashOut:Number(moves.rows[0].cash_out),expectedCash:expected,tenders:tenders.rows.map(r=>({...r,total:Number(r.total)}))}}

app.get('/api/cash/current',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const q=await pool.query("SELECT id FROM cash_sessions WHERE business_id=$1 AND status='open' AND opened_by_user_id=$2 ORDER BY id DESC LIMIT 1",[bid,req.user.id]);if(!q.rowCount)return res.json(null);res.json(await shiftSnapshot(bid,q.rows[0].id))});

app.get('/api/cash/history',auth,tenant,async(req,res)=>{const bid=await getBiz(req),limit=Math.min(100,Math.max(1,Number(req.query.limit||30)));const elevated=await hasPermission(req,bid,'shift.close');const q=await pool.query("SELECT cs.*,b.name branch_name,t.name terminal_name FROM cash_sessions cs LEFT JOIN branches b ON b.id=cs.branch_id LEFT JOIN terminals t ON t.id=cs.terminal_id WHERE cs.business_id=$1 AND ($2::boolean=true OR cs.opened_by_user_id=$3) ORDER BY cs.id DESC LIMIT $4",[bid,elevated,req.user.id,limit]);res.json(q.rows)});

app.get('/api/cash/movements',auth,tenant,async(req,res)=>{const bid=await getBiz(req),sessionId=Number(req.query.sessionId||0);if(sessionId){const own=await pool.query('SELECT 1 FROM cash_sessions WHERE id=$1 AND business_id=$2 AND opened_by_user_id=$3',[sessionId,bid,req.user.id]);if(!own.rowCount&&!await hasPermission(req,bid,'shift.close'))return res.status(403).json({error:'Not allowed to view this shift'})}res.json((await pool.query('SELECT * FROM cash_movements WHERE business_id=$1 AND ($2::bigint=0 OR session_id=$2) ORDER BY id DESC LIMIT 200',[bid,sessionId])).rows)});

app.post('/api/cash/movements',auth,tenant,async(req,res)=>{const bid=await getBiz(req),{movementType,amount,reason,reference=null}=req.body||{},value=Number(amount||0);if(!['cash_in','cash_out'].includes(movementType)||value<=0||!String(reason||'').trim())return res.status(400).json({error:'Movement type, positive amount and reason are required'});const s=await pool.query("SELECT id FROM cash_sessions WHERE business_id=$1 AND status='open' AND opened_by_user_id=$2 ORDER BY id DESC LIMIT 1",[bid,req.user.id]);if(!s.rowCount)return res.status(400).json({error:'Open your shift first'});const q=await pool.query('INSERT INTO cash_movements(business_id,session_id,movement_type,amount,reason,reference,created_by_user_id,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *',[bid,s.rows[0].id,movementType,value,String(reason).trim(),reference,req.user.id,req.user.name]);await audit(req.user,bid,'movement','cash_shift',s.rows[0].id,{movementType,amount:value,reason});res.json(q.rows[0])});

app.post('/api/cash/close',auth,tenant,async(req,res)=>{const bid=await getBiz(req),requestedId=Number(req.body?.sessionId||0)||null;let q;if(requestedId){if(!await hasPermission(req,bid,'shift.close'))return res.status(403).json({error:'Manager permission is required to close another cashier shift'});q=await pool.query("SELECT * FROM cash_sessions WHERE id=$1 AND business_id=$2 AND status='open'",[requestedId,bid])}else q=await pool.query("SELECT * FROM cash_sessions WHERE business_id=$1 AND status='open' AND opened_by_user_id=$2 ORDER BY id DESC LIMIT 1",[bid,req.user.id]);if(!q.rowCount)return res.status(404).json({error:'No open shift found'});const x=q.rows[0],snap=await shiftSnapshot(bid,x.id),actual=Math.max(0,Number(req.body?.actualCash??0)),variance=actual-Number(snap.expectedCash||0),denoms=Array.isArray(req.body?.denominations)?req.body.denominations:null,varianceReason=String(req.body?.varianceReason||'').trim()||null,closingNote=String(req.body?.closingNote||'').trim()||null;if(Math.abs(variance)>0.005&&!varianceReason)return res.status(400).json({error:'Enter a variance reason before closing a short or over shift'});const manager=await hasPermission(req,bid,'shift.close')?req.user.name:null;const u=await pool.query("UPDATE cash_sessions SET closing_cash=$1,expected_cash=$2,variance=$3,denomination_count=$4,status='closed',closed_at=now(),closed_by_user_id=$5,manager_confirmed_by=$6,manager_confirmed_at=CASE WHEN $6::text IS NULL THEN NULL ELSE now() END,variance_reason=$7,closing_note=$8 WHERE id=$9 AND status='open' RETURNING *",[actual,snap.expectedCash,variance,denoms,req.user.id,manager,varianceReason,closingNote,x.id]);if(!u.rowCount)return res.status(409).json({error:'Shift was already closed'});await audit(req.user,bid,'close','cash_shift',x.id,{shiftNo:x.shift_no,expected:snap.expectedCash,actual,variance,varianceReason});res.json({...u.rows[0],cashSales:snap.cashSales,refunds:snap.refunds,cashIn:snap.cashIn,cashOut:snap.cashOut,tenders:snap.tenders})});

app.get('/api/documents/cash-session/:id/pdf',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),snap=await shiftSnapshot(bid,id);if(!snap)return res.status(404).json({error:'Shift not found'});const own=Number(snap.opened_by_user_id)===Number(req.user.id);if(!own&&!await hasPermission(req,bid,'shift.close'))return res.status(403).json({error:'Not allowed to view this shift'});const [bq,mq]=await Promise.all([pool.query('SELECT * FROM businesses WHERE id=$1',[bid]),pool.query('SELECT * FROM cash_movements WHERE session_id=$1 ORDER BY id',[id])]);const b=bq.rows[0],x=snap,isOpen=x.status==='open',docType=isOpen?'x_report':'z_report',title=isOpen?'SHIFT / X REPORT':'SHIFT / Z REPORT';await recordPrint(bid,req.user.name,docType,'cash_session',id,x.shift_no||('SHIFT-'+id),'A4');res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition','inline; filename="'+(x.shift_no||('SHIFT-'+id))+'-'+docType+'.pdf"');const doc=new PDFDocument({size:'A4',margin:42,info:{Title:title,Author:b.name||'MauzoPOS'}});doc.pipe(res);pdfHeader(doc,b,title,x.shift_no||('SHIFT-'+id));pdfMetaGrid(doc,[['Cashier',x.opened_by||'-'],['Branch',x.branch_name||'-'],['Terminal',x.terminal_name||'-'],['Opened',new Date(x.opened_at).toLocaleString()],['Closed',x.closed_at?new Date(x.closed_at).toLocaleString():'Still open'],['Status',niceText(x.status)]]);const variance=Number(x.variance||0);pdfMetricCards(doc,b,[{label:'Opening Float',value:pdfMoney(b,x.opening_cash)},{label:'Cash Sales',value:pdfMoney(b,x.cashSales)},{label:'Expected Cash',value:pdfMoney(b,x.expectedCash)},{label:isOpen?'Current Variance':'Variance',value:isOpen?'Pending count':pdfMoney(b,variance),tone:!isOpen&&Math.abs(variance)>.005?'danger':undefined}]);pdfSectionTitle(doc,'Cash Reconciliation','How expected cash was derived');pdfTable(doc,b,['Item','Amount'],[['Opening float',Number(x.opening_cash||0)],['Cash sales',Number(x.cashSales||0)],['Cash refunds',-Number(x.refunds||0)],['Cash in',Number(x.cashIn||0)],['Cash out',-Number(x.cashOut||0)],['Expected cash',Number(x.expectedCash||0)],...(!isOpen?[['Physical cash',Number(x.closing_cash||0)],['Variance',variance]]:[])],{title,number:x.shift_no||('SHIFT-'+id),fontSize:8.2});if(Array.isArray(x.tenders)&&x.tenders.length){pdfSectionTitle(doc,'Tender Summary','Payments captured during this shift');pdfTable(doc,b,['Payment Method','Transactions','Total'],x.tenders.map(t=>[niceText(t.payment_method),Number(t.transactions||0),Number(t.total||0)]),{title,number:x.shift_no||('SHIFT-'+id),fontSize:8})}if(mq.rows.length){pdfSectionTitle(doc,'Cash Movements','Manual cash additions and removals');pdfTable(doc,b,['Time','Type','Reason','Amount','By'],mq.rows.map(m=>[new Date(m.created_at).toLocaleString(),niceText(m.movement_type),m.reason,Number(m.movement_type==='cash_out'?-m.amount:m.amount),m.created_by||'-']),{title,number:x.shift_no||('SHIFT-'+id),fontSize:7.4})}if(x.variance_reason||x.closing_note){pdfSectionTitle(doc,'Closing Notes');const noteY=doc.y,txt=[x.variance_reason?'Variance reason: '+x.variance_reason:null,x.closing_note?'Closing note: '+x.closing_note:null].filter(Boolean).join('\n');doc.roundedRect(42,noteY,doc.page.width-84,Math.max(46,doc.heightOfString(txt,{width:doc.page.width-110})+22),6).fill('#F8FAFC');doc.font('Helvetica').fontSize(8.5).fillColor('#475569').text(txt,55,noteY+11,{width:doc.page.width-110});doc.y=noteY+58}pdfFooter(doc,b);doc.end()});

app.get('*',(req,res)=>res.sendFile(process.cwd()+'/public/index.html'));
init().then(()=>app.listen(port,'0.0.0.0',()=>console.log('POS running on '+port))).catch(e=>{console.error(e);process.exit(1)});
